    macro_rules! world_recipes {
        ($s:ident) => {
            match &$s .world_tables { Some(t) => & t.recipes, None => $s .res.recipes(),
            }
        };
    }
    macro_rules! world_stations {
        ($s:ident) => {
            match &$s .world_tables { Some(t) => & t.stations, None => $s .res
            .stations(), }
        };
    }
