                        let (bx, by) = (((w - 200.0) / 2.0).trunc(), top + 33.0);
                        let hover = ui::hovered(cursor, bx, by, 200.0, 20.0);
                        ui::action_button(
                            batch,
                            atlas,
                            widgets::Action::Back,
                            bx,
                            by,
                            200.0,
                            20.0,
                            &label,
                            active,
                            hover,
                        );
