                fn signed_chat_line_body(
                    &mut self,
                    content: horizon_client::text::Text,
                    source: horizon_client::chat::ChatSource,
                    signature: Option<Signature>,
                    trust: ChatTrust,
                ) -> bool {
                    if !self.ui.chat.shows(source) {
                        return false;
                    }
                    let text = content.plain();
                    let focused = self.screen == Screen::Chat;
                    if source == horizon_client::chat::ChatSource::Player {
                        self.ui
                            .chat
                            .add_signed(
                                &self.gui.atlas,
                                ({
                                    fn sunset_debug_chat_signed(
                                        value: horizon_client::text::Text,
                                    ) -> horizon_client::text::Text {
                                        if !::sunset_core::lifecycle::RUNTIME.running() {
                                            return value;
                                        }
                                        ::sunset_core::chat_log::added(
                                            &value.strip_legacy().plain(),
                                            horizon_client::chat::ChatSource::Player as u8,
                                        );
                                        crate::game::sunset_streamer::protect(&value)
                                            .unwrap_or(value)
                                    }
                                    sunset_debug_chat_signed
                                })(content),
                                signature,
                                trust.tag(),
                                self.visual_ticks(),
                                focused,
                            );
                    } else {
                        let indicator = Some(horizon_client::chat::SYSTEM_INDICATOR);
                        self.ui
                            .chat
                            .add(
                                &self.gui.atlas,
                                content,
                                indicator,
                                source,
                                self.visual_ticks(),
                                focused,
                            );
                    }
                    if let Some(r) = self.remote.as_mut() {
                        r.chat.push((text, Instant::now()));
                        r.chat_received += 1;
                        if r.chat.len() > 100 {
                            r.chat.remove(0);
                        }
                    }
                    true
                }
