            pub(crate) fn server_menu_click(
                game: &mut Game<'_>,
                window: i32,
                slot: usize,
            ) -> bool {
                use horizon_protocol::packets::play::{self, Serverbound as S};
                let (open, menu) = game.remote_menu();
                if window == 0 || open != window || game.carried.is_some() {
                    return false;
                }
                let Some(index) = crate::game::Game::menu_slot_index(&menu, slot) else {
                    return false
                };
                let Some(remote) = game.remote.as_ref() else { return false };
                let state = remote.state_id;
                game.send(
                    S::ContainerClick(play::ContainerClick {
                        container: window,
                        state,
                        slot: index as i16,
                        button: 0,
                        input: 0,
                        changed: Vec::new(),
                        carried: None,
                    }),
                );
                true
            }
