            #[test]
            fn ghost_hand_hits_move_to_hit_through_walls() {
                let out = fields(
                    "ghosthand.on=true\nghosthand.blocks=false\nghosthand.hits=true\nghosthand.cutthrough=true\n",
                );
                assert_eq!(out["hitthroughwalls.on"], "true");
                assert_eq!(out["hitthroughwalls.mode"], "Any block");
                assert_eq!(out["hitthroughwalls.ignorepassive"], "false");
                assert_eq!(out["ghosthand.blocks"], "false");
                assert!(
                    ! out.contains_key("ghosthand.hits") && ! out
                    .contains_key("ghosthand.cutthrough")
                );
                let out = fields(
                    "ghosthand.on=false\nghosthand.hits=false\nghosthand.cutthrough=true\n",
                );
                assert_eq!(out["hitthroughwalls.on"], "false");
                assert_eq!(out["hitthroughwalls.mode"], "Passable only");
                let out = fields(
                    "ghosthand.on=true\nghosthand.hits=false\nghosthand.cutthrough=false\n",
                );
                assert!(
                    ! out.contains_key("hitthroughwalls.on") && ! out
                    .contains_key("ghosthand.hits")
                );
                let out = fields(
                    "ghosthand.on=true\nghosthand.hits=true\nhitthroughwalls.on=false\nhitthroughwalls.mode=Passable only\n",
                );
                assert_eq!(out["hitthroughwalls.on"], "false");
                assert_eq!(out["hitthroughwalls.mode"], "Passable only");
            }
