        fn command(name: &str) -> Option<&'static Command> {
            let name = name.to_ascii_lowercase();
            COMMANDS
                .iter()
                .find(|c| c.name == name || c.aliases.contains(&name.as_str()))
        }
        fn modules(src: &dyn Source) -> Vec<Suggestion> {
            modules_where(src, |_| true)
        }
        fn switched(src: &dyn Source) -> Vec<Suggestion> {
            modules_where(src, |m| !m.gui_only)
        }
        fn modules_where(
            src: &dyn Source,
            keep: impl Fn(&ModuleInfo) -> bool,
        ) -> Vec<Suggestion> {
            src.modules()
                .into_iter()
                .filter(|m| keep(m))
                .map(|m| {
                    let state = if m.on { "on" } else { "off" };
                    Suggestion::new(
                            norm(&m.name),
                            format!("{} ({state}): {}", m.name, m.about),
                        )
                        .also(m.name)
                })
                .collect()
        }
        fn module_word(src: &dyn Source, word: &str) -> Result<ModuleInfo, Step> {
            src.find_module(word)
                .ok_or_else(|| Step::Bad(format!("No module called {word}")))
        }
        fn one_module(src: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => pick(modules(src), "<module>", "No module called"),
                _ => Step::Done,
            }
        }
        fn gui_only(src: &dyn Source, word: &str, why: &str) -> Option<Step> {
            src.find_module(word)
                .filter(|m| m.gui_only)
                .map(|m| Step::Bad(format!("{} {why}", m.name)))
        }
        fn toggle(src: &dyn Source, before: &[&str], partial: &str) -> Step {
            match before {
                [] => {
                    gui_only(src, partial, "only turns on in the ClickGUI")
                        .unwrap_or_else(|| pick(
                            switched(src),
                            "<module>",
                            "No module called",
                        ))
                }
                [module] => {
                    match module_word(src, module) {
                        Ok(m) if m.gui_only => {
                            Step::Bad(
                                format!("{} only turns on in the ClickGUI", m.name),
                            )
                        }
                        Ok(_) => Step::Done,
                        Err(bad) => bad,
                    }
                }
                _ => Step::Done,
            }
        }
        fn menu(src: &dyn Source, before: &[&str], _: &str) -> Step {
            Step::Free {
                list: modules(src),
                usage: "[search]".into(),
                back: before.len(),
            }
        }
        fn number_usage(now: f64, min: f64, max: f64, step: f64) -> String {
            let show = |v: f64| {
                let s = format!("{v:.2}");
                let s = s.trim_end_matches('0').trim_end_matches('.').to_owned();
                if s == "-0" { "0".to_owned() } else { s }
            };
            let whole = step >= 1.0 && min.fract() == 0.0 && max.fract() == 0.0;
            format!(
                "<{} {} to {}> (now {})", if whole { "whole number" } else { "number" },
                show(min), show(max), show(now)
            )
        }
        fn value_text(kind: &Kind) -> String {
            match kind {
                Kind::Bool(b) => if *b { "ON" } else { "OFF" }.to_owned(),
                Kind::Number { now, .. } => {
                    let s = format!("{now:.2}");
                    s.trim_end_matches('0').trim_end_matches('.').to_owned()
                }
                Kind::Pick { now, of } => of.get(*now).cloned().unwrap_or_default(),
                Kind::Text(t) if t.is_empty() => "(empty)".to_owned(),
                Kind::Text(t) => t.chars().take(40).collect(),
            }
        }
        fn set(src: &dyn Source, before: &[&str], partial: &str) -> Step {
            let Some((module, words)) = before.split_first() else {
                return pick(
                    modules(src),
                    "<module> <setting> <value>",
                    "No module called",
                );
            };
            let module = match module_word(src, module) {
                Ok(m) => m,
                Err(bad) => return bad,
            };
            let settings = src.settings(&module.name);
            if settings.is_empty() {
                return Step::Bad(format!("{} has no settings", module.name));
            }
            let names = || {
                settings
                    .iter()
                    .map(|s| {
                        Suggestion::new(
                                norm(&s.name),
                                format!("{}: {}", s.name, value_text(& s.kind)),
                            )
                            .also(s.name.clone())
                    })
                    .collect::<Vec<_>>()
            };
            if words.is_empty() {
                return ordered(
                    names(),
                    "<setting> <value>",
                    format!("{} has no setting called", module.name),
                );
            }
            let find = |exact: bool| {
                (1..=words.len())
                    .rev()
                    .find_map(|k| {
                        let name = norm(&words[..k].join(""));
                        settings
                            .iter()
                            .find(|s| {
                                if exact {
                                    norm(&s.name) == name
                                } else {
                                    norm(&s.name).starts_with(&name)
                                }
                            })
                            .map(|s| (k, s))
                    })
            };
            let found = find(true);
            let all = norm(&format!("{}{partial}", words.join("")));
            let longer = settings
                .iter()
                .any(|s| {
                    let n = norm(&s.name);
                    n.starts_with(&all)
                        && found
                            .is_none_or(|(k, f)| n != norm(&f.name) && k == words.len())
                });
            if longer && (found.is_none() || !partial.is_empty()) {
                return Step::Pick {
                    list: names(),
                    usage: "<setting> <value>".into(),
                    strict: Some(format!("{} has no setting called", module.name)),
                    back: words.len(),
                    ordered: true,
                };
            }
            let Some((k, setting)) = found.or_else(|| find(false)) else {
                return Step::Bad(
                    format!("{} has no setting called {}", module.name, words.join(" ")),
                );
            };
            let back = words.len() - k;
            let now = value_text(&setting.kind);
            match &setting.kind {
                Kind::Bool(b) => {
                    Step::Pick {
                        list: vec![
                            Suggestion::new("on", if * b { "now on" } else { "turn it on"
                            }), Suggestion::new("off", if * b { "turn it off" } else {
                            "now off" }), Suggestion::new("toggle", "the other way"),
                        ],
                        usage: format!("<on|off|toggle> (now {now})"),
                        strict: Some(format!("{} is on or off, not", setting.name)),
                        back,
                        ordered: true,
                    }
                }
                Kind::Number { now, min, max, step } => {
                    Step::Free {
                        list: Vec::new(),
                        usage: number_usage(*now, *min, *max, *step),
                        back,
                    }
                }
                Kind::Pick { now, of } => {
                    Step::Pick {
                        list: of
                            .iter()
                            .enumerate()
                            .map(|(i, o)| Suggestion::new(
                                o.clone(),
                                if i == *now { "now" } else { "" },
                            ))
                            .collect(),
                        usage: format!(
                            "<{}> (now {})", of.join("|"), value_text(& setting.kind)
                        ),
                        strict: Some(
                            format!("{} is one of {}, not", setting.name, of.join(", ")),
                        ),
                        back,
                        ordered: true,
                    }
                }
                Kind::Text(_) => {
                    Step::Free {
                        list: Vec::new(),
                        usage: format!("<text> (now {now})"),
                        back,
                    }
                }
            }
        }
