        fn bind(src: &dyn Source, before: &[&str], partial: &str) -> Step {
            match before {
                [] => {
                    gui_only(src, partial, "takes no bind: turn it on in the ClickGUI")
                        .unwrap_or_else(|| pick(
                            switched(src),
                            "<module> <key|mouse4|none>",
                            "No module called",
                        ))
                }
                [module] => {
                    let module = match module_word(src, module) {
                        Ok(m) if m.gui_only => {
                            return Step::Bad(
                                format!(
                                    "{} takes no bind: turn it on in the ClickGUI", m.name
                                ),
                            );
                        }
                        Ok(m) => m,
                        Err(bad) => return bad,
                    };
                    let now = module
                        .key
                        .as_deref()
                        .map_or(
                            "none".to_owned(),
                            |k| {
                                k.trim_start_matches("key.keyboard.")
                                    .trim_start_matches("key.")
                                    .to_owned()
                            },
                        );
                    let list = KEYS
                        .iter()
                        .map(|k| Suggestion::new(
                            *k,
                            if *k == "none" { "no key" } else { "" },
                        ))
                        .collect();
                    Step::Pick {
                        list,
                        usage: format!("<key|mouse4|none> (now {now})"),
                        strict: None,
                        back: 0,
                        ordered: true,
                    }
                }
                _ => Step::Done,
            }
        }
        fn profile(src: &dyn Source, before: &[&str], _: &str) -> Step {
            const SUBS: &[(&str, &str)] = &[
                ("save", "keep the current settings under a name"),
                ("load", "bring a profile's settings back"),
                ("delete", "delete a profile"),
                ("export", "copy a profile to the exports folder, to share"),
                (
                    "import",
                    "choose .profile files to keep (or name one of the imports folder)",
                ),
                ("copy", "put a profile's text on the clipboard, to send"),
                ("paste", "keep the profile whose text is on the clipboard"),
                ("list", "the profiles, and the one in use"),
            ];
            let Some((sub, name)) = before.split_first() else {
                return ordered(
                    words(SUBS),
                    "save|load|delete|export|import|copy|paste|list [name]",
                    "Profile: use save, load, delete, export, import, copy, paste or list, not",
                );
            };
            let back = name.len();
            let names = |src: &dyn Source| {
                src.profiles()
                    .into_iter()
                    .map(|p| Suggestion::new(p, "profile"))
                    .collect::<Vec<_>>()
            };
            match sub.to_ascii_lowercase().as_str() {
                "list" => Step::Done,
                "save" => {
                    Step::Free {
                        list: names(src),
                        usage: "<name>".into(),
                        back,
                    }
                }
                "load" => {
                    let mut list = names(src);
                    list.push(
                        Suggestion::new(
                            "before-load",
                            "the settings before the last load",
                        ),
                    );
                    Step::Pick {
                        list,
                        usage: "<name>".into(),
                        strict: Some("No profile called".into()),
                        back,
                        ordered: false,
                    }
                }
                "delete" | "export" | "copy" => {
                    Step::Pick {
                        list: names(src),
                        usage: "<name>".into(),
                        strict: Some("No profile called".into()),
                        back,
                        ordered: false,
                    }
                }
                "paste" => {
                    Step::Free {
                        list: names(src),
                        usage: "<name> [keep|replace]".into(),
                        back,
                    }
                }
                "import" => {
                    let list = src
                        .imports("profile")
                        .into_iter()
                        .map(|p| Suggestion::new(p, "in the imports folder"))
                        .collect();
                    Step::Pick {
                        list,
                        usage: "<name>".into(),
                        strict: Some("No profile in the imports folder called".into()),
                        back,
                        ordered: false,
                    }
                }
                other => {
                    Step::Bad(
                        format!(
                            "Profile: use save, load, delete, export, import, copy, paste or list, not {other}"
                        ),
                    )
                }
            }
        }
        fn preset(src: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => {
                    let list = src
                        .presets()
                        .into_iter()
                        .map(|(id, about)| Suggestion::new(id, about))
                        .collect();
                    pick(list, "[name] [apply]", "No preset called")
                }
                [name] => {
                    if !src.presets().iter().any(|(id, _)| id.eq_ignore_ascii_case(name))
                    {
                        return Step::Bad(format!("No preset called {name}"));
                    }
                    pick(
                        words(
                            &[("apply", "take it (.profile load before-load undoes it)")],
                        ),
                        "[apply]",
                        "Use apply, not",
                    )
                }
                _ => Step::Done,
            }
        }
        fn movement_preset(_: &dyn Source, before: &[&str], _: &str) -> Step {
            if !before.is_empty() {
                return Step::Done;
            }
            ordered(
                words(
                    &[
                        ("subtle", "small changes"),
                        ("balanced", "between the two"),
                        ("aggressive", "the most movement"),
                    ],
                ),
                "<subtle|balanced|aggressive>",
                "Use subtle, balanced or aggressive, not",
            )
        }
        fn friend(src: &dyn Source, before: &[&str], _: &str) -> Step {
            const SUBS: &[(&str, &str)] = &[
                ("add", "make a player a friend"),
                ("remove", "no longer a friend"),
                ("list", "your friends"),
            ];
            match (lower(before.first()).as_str(), before.len()) {
                (_, 0) => {
                    ordered(
                        words(SUBS),
                        "add|remove|list [name]",
                        "Friend: use add, remove or list, not",
                    )
                }
                ("add", 1) => {
                    let friends = src.friends();
                    let list = src
                        .players()
                        .into_iter()
                        .filter(|p| !friends.iter().any(|f| f.eq_ignore_ascii_case(p)))
                        .map(|p| Suggestion::new(p, "online"))
                        .collect();
                    Step::Free {
                        list,
                        usage: "<name>".into(),
                        back: 0,
                    }
                }
                ("remove" | "del" | "rm", 1) => {
                    let list = src
                        .friends()
                        .into_iter()
                        .map(|f| Suggestion::new(f, "friend"))
                        .collect();
                    pick(list, "<name>", "No friend called")
                }
                ("add" | "remove" | "del" | "rm" | "list", _) => Step::Done,
                (other, _) => {
                    Step::Bad(format!("Friend: use add, remove or list, not {other}"))
                }
            }
        }
        fn waypoint(src: &dyn Source, before: &[&str], _: &str) -> Step {
            const SUBS: &[(&str, &str)] = &[
                ("add", "save the place you stand"),
                ("remove", "delete a waypoint"),
                ("list", "your waypoints"),
            ];
            match (lower(before.first()).as_str(), before.len()) {
                (_, 0) => {
                    ordered(
                        words(SUBS),
                        "add|remove|list [name]",
                        "Waypoint: use add, remove or list, not",
                    )
                }
                ("add" | "set", 1) => free("<name>"),
                ("remove" | "del" | "rm", 1) => {
                    let list = src
                        .waypoints()
                        .into_iter()
                        .map(|w| Suggestion::new(w, "waypoint"))
                        .collect();
                    pick(list, "<name>", "No waypoint called")
                }
                ("add" | "set" | "remove" | "del" | "rm" | "list", _) => Step::Done,
                (other, _) => {
                    Step::Bad(format!("Waypoint: use add, remove or list, not {other}"))
                }
            }
        }
        fn loadout(src: &dyn Source, before: &[&str], _: &str) -> Step {
            const SUBS: &[(&str, &str)] = &[
                ("save", "keep what you wear and hold under a name"),
                ("delete", "delete a loadout"),
                ("export", "copy a loadout to the exports folder"),
                ("import", "keep a loadout from the imports folder"),
                ("list", "your loadouts"),
            ];
            let names = |src: &dyn Source, tip: &str| {
                src.loadouts()
                    .into_iter()
                    .map(|l| Suggestion::new(l, tip))
                    .collect::<Vec<_>>()
            };
            let Some((sub, name)) = before.split_first() else {
                let mut list = words(SUBS);
                list.extend(names(src, "put it on"));
                return Step::Free {
                    list,
                    usage: "save|delete|export|import|list|<name>".into(),
                    back: 0,
                };
            };
            let back = name.len();
            match sub.to_ascii_lowercase().as_str() {
                "list" => Step::Done,
                "save" | "add" => {
                    Step::Free {
                        list: Vec::new(),
                        usage: "[name]".into(),
                        back,
                    }
                }
                "delete" | "del" | "remove" | "rm" | "export" => {
                    Step::Pick {
                        list: names(src, "loadout"),
                        usage: "<name>".into(),
                        strict: Some("No loadout called".into()),
                        back,
                        ordered: false,
                    }
                }
                "import" => {
                    let list = src
                        .imports("loadout")
                        .into_iter()
                        .map(|p| Suggestion::new(p, "in the imports folder"))
                        .collect();
                    Step::Pick {
                        list,
                        usage: "<name>".into(),
                        strict: None,
                        back,
                        ordered: false,
                    }
                }
                _ => {
                    Step::Free {
                        list: names(src, "put it on"),
                        usage: "<name>".into(),
                        back: before.len(),
                    }
                }
            }
        }
        fn coordinates(src: &dyn Source, done: usize) -> Vec<Suggestion> {
            let Some(at) = src.position() else {
                return Vec::new();
            };
            let rest: Vec<String> = at[done.min(3)..]
                .iter()
                .map(i32::to_string)
                .collect();
            (1..=rest.len())
                .rev()
                .map(|n| Suggestion::new(rest[..n].join(" "), "where you stand"))
                .collect()
        }
        fn coordinate_step(src: &dyn Source, coords: &[&str]) -> Step {
            if let Some(bad) = coords.iter().find(|c| c.parse::<i32>().is_err()) {
                return Step::Bad(format!("{bad} is not a whole block coordinate"));
            }
            if coords.len() >= 3 {
                return Step::Done;
            }
            let usage = ["<x>", "<y>", "<z>"][coords.len()..].join(" ");
            Step::Free {
                list: coordinates(src, coords.len()),
                usage,
                back: 0,
            }
        }
        fn follow(src: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => {
                    let mut list: Vec<Suggestion> = src
                        .players()
                        .into_iter()
                        .map(|p| Suggestion::new(p, "online"))
                        .collect();
                    list.push(Suggestion::new("stop", "stop following"));
                    Step::Free {
                        list,
                        usage: "<player> [blocks]|stop".into(),
                        back: 0,
                    }
                }
                [word] if word.eq_ignore_ascii_case("stop") => Step::Done,
                [_] => {
                    Step::Free {
                        list: vec![
                            Suggestion::new("3", "blocks to stay away (1 to 16)")
                        ],
                        usage: "[blocks]".into(),
                        back: 0,
                    }
                }
                [_, blocks,
                ] if blocks.parse::<f64>().is_ok_and(|b| (1.0..=16.0).contains(&b)) => {
                    Step::Done
                }
                [_, blocks] => {
                    Step::Bad(format!("{blocks} is not a distance from 1 to 16 blocks"))
                }
                _ => Step::Bad("Use .follow <player> [blocks] or .follow stop".into()),
            }
        }
        fn mine(_: &dyn Source, before: &[&str], _: &str) -> Step {
            const KINDS: &[(&str, &str)] = &[
                ("coal", "coal ore"),
                ("copper", "copper ore"),
                ("iron", "iron ore"),
                ("lapis", "lapis ore"),
                ("redstone", "redstone ore"),
                ("gold", "gold ore"),
                ("diamond", "diamond ore"),
                ("emerald", "emerald ore"),
                ("quartz", "nether quartz ore"),
                ("debris", "ancient debris"),
                ("log", "any log"),
                ("stop", "stop mining"),
            ];
            match before {
                [] => {
                    Step::Free {
                        list: words(KINDS),
                        usage: "<block> [count]|stop".into(),
                        back: 0,
                    }
                }
                [word] if word.eq_ignore_ascii_case("stop") => Step::Done,
                [_] => {
                    Step::Free {
                        list: Vec::new(),
                        usage: "[count]".into(),
                        back: 0,
                    }
                }
                [_, count,
                ] if count.parse::<u32>().is_ok_and(|n| (1..=1024).contains(&n)) => {
                    Step::Done
                }
                [_, count] => {
                    Step::Bad(
                        format!("{count} is not a number of blocks from 1 to 1024"),
                    )
                }
                _ => Step::Bad("Use .mine <block> [count] or .mine stop".into()),
            }
        }
        fn highway(_: &dyn Source, before: &[&str], _: &str) -> Step {
            let usage = "Use .highway <width> [height] [length] [rails] [nofloor] or .highway stop";
            if before.is_empty() {
                let list = words(
                    &[("4", "blocks wide (1 to 5)"), ("stop", "stop building")],
                );
                return Step::Free {
                    list,
                    usage: "<width> [height] [length] [rails] [nofloor]|stop".into(),
                    back: 0,
                };
            }
            if before.len() == 1 && before[0].eq_ignore_ascii_case("stop") {
                return Step::Done;
            }
            let (mut sizes, mut rails, mut nofloor) = (0, false, false);
            for word in before {
                match word.to_ascii_lowercase().as_str() {
                    "rails" if sizes > 0 => rails = true,
                    "nofloor" if sizes > 0 => nofloor = true,
                    number => {
                        let (Ok(n), Some((what, lo, hi))) = (
                            number.parse::<u32>(),
                            [("width", 1, 5), ("height", 2, 5), ("length", 1, 10_000)]
                                .get(sizes)
                                .copied(),
                        ) else {
                            return Step::Bad(usage.into());
                        };
                        if !(lo..=hi).contains(&n) {
                            return Step::Bad(
                                format!("{n} is not a {what} from {lo} to {hi}"),
                            );
                        }
                        sizes += 1;
                    }
                }
            }
            let mut list = Vec::new();
            match sizes {
                1 => list.push(Suggestion::new("3", "blocks high (2 to 5)")),
                2 => {
                    list.push(
                        Suggestion::new("100", "blocks long (without it: until stopped)"),
                    )
                }
                _ => {}
            }
            if !rails {
                list.push(Suggestion::new("rails", "a block along each edge"));
            }
            if !nofloor {
                list.push(
                    Suggestion::new("nofloor", "leave holes in the floor as they are"),
                );
            }
            if list.is_empty() {
                Step::Done
            } else {
                Step::Free {
                    list,
                    usage: "[height] [length] [rails] [nofloor]".into(),
                    back: 0,
                }
            }
        }
        fn excavate(src: &dyn Source, before: &[&str], _: &str) -> Step {
            if before.first().is_some_and(|w| w.eq_ignore_ascii_case("stop")) {
                return if before.len() == 1 {
                    Step::Done
                } else {
                    Step::Bad(
                        "Use .excavate <x1> <y1> <z1> <x2> <y2> <z2> or .excavate stop"
                            .into(),
                    )
                };
            }
            if let Some(bad) = before.iter().find(|c| c.parse::<i32>().is_err()) {
                return Step::Bad(format!("{bad} is not a whole block coordinate"));
            }
            if before.len() >= 6 {
                return Step::Done;
            }
            let mut list = coordinates(src, before.len() % 3);
            if before.is_empty() {
                list.push(Suggestion::new("stop", "stop excavating"));
            }
            let usage = ["<x1>", "<y1>", "<z1>", "<x2>", "<y2>", "<z2>"][before.len()..]
                .join(" ");
            Step::Free {
                list,
                usage: if before.is_empty() { format!("{usage}|stop") } else { usage },
                back: 0,
            }
        }
        fn goto(src: &dyn Source, before: &[&str], _: &str) -> Step {
            if before.first().is_some_and(|w| w.eq_ignore_ascii_case("stop")) {
                return if before.len() == 1 {
                    Step::Done
                } else {
                    Step::Bad("Use .goto <x> <y> <z> or .goto stop".into())
                };
            }
            if before.is_empty() {
                let mut list = coordinates(src, 0);
                list.push(Suggestion::new("stop", "stop walking"));
                return Step::Free {
                    list,
                    usage: "<x> <y> <z>|stop".into(),
                    back: 0,
                };
            }
            coordinate_step(src, before)
        }
        fn baritone(src: &dyn Source, before: &[&str], _: &str) -> Step {
            const SUBS: &[(&str, &str)] = &[
                ("status", "what Baritone is doing"),
                ("goto", "walk to a block"),
                ("mine", "mine blocks you can see, or Ore Sim's ores"),
                ("stop", "stop and let go of the controls"),
                ("off", "turn Baritone off"),
                ("targets", "the mining targets it knows"),
                ("help", "all of Baritone's commands"),
            ];
            let Some((sub, rest)) = before.split_first() else {
                return ordered(
                    words(SUBS),
                    "status|goto|mine|stop|off|targets|help",
                    "Baritone: no command",
                );
            };
            match (sub.to_ascii_lowercase().as_str(), rest) {
                ("goto", coords) => coordinate_step(src, coords),
                ("mine", []) => {
                    Step::Free {
                        list: words(&[("oresim", "the ores Ore Sim predicts")]),
                        usage: "[block[,block...]] | oresim [ore[,ore...]]".into(),
                        back: 0,
                    }
                }
                ("mine", [w]) if w.eq_ignore_ascii_case("oresim") => {
                    free("[ore[,ore...]]")
                }
                ("targets", []) => free("[1..64]"),
                ("status" | "stop" | "off" | "help" | "mine" | "targets", _) => {
                    Step::Done
                }
                (other, _) => Step::Bad(format!("Baritone: no command {other}")),
            }
        }
        fn blocks(_: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => free("<blocks>"),
                [b] if b.parse::<f64>().is_err() => {
                    Step::Bad(format!("{b} is not a number of blocks"))
                }
                _ => Step::Done,
            }
        }
        fn seed(_: &dyn Source, before: &[&str], _: &str) -> Step {
            if !before.is_empty() {
                return Step::Free {
                    list: Vec::new(),
                    usage: "<seed>".into(),
                    back: before.len(),
                };
            }
            Step::Free {
                list: words(
                    &[
                        ("status", "the seed and the search's progress"),
                        ("auto", "find the seed by itself"),
                        ("clear", "forget the seed"),
                        ("restart", "search again"),
                    ],
                ),
                usage: "[status|auto|clear|restart|<seed>]".into(),
                back: 0,
            }
        }
        fn scan(_: &dyn Source, before: &[&str], _: &str) -> Step {
            const VIEWS: &[(&str, &str)] = &[
                ("summary", "what was found"),
                ("plugins", "the server's plugins"),
                ("details", "every finding"),
                ("channels", "the plugin channels"),
                ("commands", "the server's commands"),
                ("status", "what the scan is doing"),
                ("run", "run the Extended checks now"),
            ];
            match (lower(before.first()).as_str(), before.len()) {
                (_, 0) => {
                    ordered(
                        words(VIEWS),
                        "[plugins|details|channels|commands|status|run] [page]",
                        "Server Scan has no view",
                    )
                }
                ("plugins" | "details" | "channels", 1) => free("[page]"),
                ("commands", 1) => free("[command] [page]"),
                ("commands", 2) => free("[page]"),
                _ => Step::Done,
            }
        }
        fn relog(_: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => free("[delay seconds]"),
                [s] if s.parse::<f64>().is_err() => {
                    Step::Bad(format!("{s} is not a number of seconds"))
                }
                _ => Step::Done,
            }
        }
        fn debug(_: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => free("[chat lines]"),
                [n] if n.parse::<usize>().is_err() => {
                    Step::Bad(format!("{n} is not a number of chat lines"))
                }
                _ => Step::Done,
            }
        }
        fn vanish(_: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => {
                    pick(
                        words(&[("debug", "Anti Vanish's HorizonSMP evidence")]),
                        "debug",
                        "Use .vanish debug, not",
                    )
                }
                _ => Step::Done,
            }
        }
        fn staffcheck(_: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => {
                    Step::Free {
                        list: words(&[("test", "send it a fake push")]),
                        usage: "[test [x y z]]".into(),
                        back: 0,
                    }
                }
                [t, push @ ..] if t.eq_ignore_ascii_case("test") && push.len() < 3 => {
                    free(["[x]", "[y]", "[z]"][push.len()..].join(" "))
                }
                _ => Step::Done,
            }
        }
        fn antibot(_: &dyn Source, before: &[&str], _: &str) -> Step {
            match before {
                [] => free("[entity id]"),
                _ => Step::Done,
            }
        }
        fn tokens(s: &str) -> Vec<(usize, &str)> {
            let mut out = Vec::new();
            let mut start = None;
            for (i, c) in s.char_indices() {
                match (c.is_whitespace(), start) {
                    (true, Some(at)) => {
                        out.push((at, &s[at..i]));
                        start = None;
                    }
                    (false, None) => start = Some(i),
                    _ => {}
                }
            }
            if let Some(at) = start {
                out.push((at, &s[at..]));
            }
            out
        }
        fn fit(s: &Suggestion, typed: &str) -> Option<u8> {
            if typed.is_empty()
                || s.text.to_lowercase().starts_with(&typed.to_lowercase())
            {
                return Some(0);
            }
            let n = norm(typed);
            if n.is_empty() {
                return None;
            }
            if norm(&s.text).starts_with(&n) || norm(&s.also).starts_with(&n) {
                return Some(1);
            }
            let words = s
                .also
                .split(|c: char| !c.is_ascii_alphanumeric())
                .chain(s.text.split(|c: char| !c.is_ascii_alphanumeric()));
            words.filter(|w| !w.is_empty()).any(|w| norm(w).starts_with(&n)).then_some(2)
        }
        fn matching(
            mut list: Vec<Suggestion>,
            typed: &str,
            ordered: bool,
        ) -> Vec<Suggestion> {
            if !ordered {
                list.sort_by(|a, b| a.text.to_lowercase().cmp(&b.text.to_lowercase()));
            }
            let mut seen = std::collections::HashSet::new();
            list.retain(|s| seen.insert(s.text.to_lowercase()));
            let mut fits: Vec<(u8, Suggestion)> = list
                .into_iter()
                .filter_map(|s| fit(&s, typed).map(|f| (f, s)))
                .collect();
            fits.sort_by_key(|(f, _)| *f);
            let out: Vec<Suggestion> = fits.into_iter().map(|(_, s)| s).collect();
            if out.len() == 1 && out[0].text.eq_ignore_ascii_case(typed) {
                return Vec::new();
            }
            out
        }
        fn command_names(src: &dyn Source, typed: &str) -> Vec<Suggestion> {
            let mut list = Vec::new();
            for c in COMMANDS {
                let usage = if c.usage.is_empty() {
                    String::new()
                } else {
                    format!(" {}", c.usage)
                };
                let main = Suggestion::new(
                    c.name,
                    format!(".{}{usage}: {}", c.name, c.about),
                );
                if fit(&main, typed) == Some(0) || typed.is_empty() {
                    list.push(main);
                } else if let Some(alias) = c
                    .aliases
                    .iter()
                    .find(|a| a.starts_with(&typed.to_lowercase()))
                {
                    list.push(
                        Suggestion::new(
                            *alias,
                            format!(".{}{usage}: {}", c.name, c.about),
                        ),
                    );
                } else {
                    list.push(main);
                }
            }
            for (name, about) in src.plugin_commands() {
                list.push(Suggestion::new(name.clone(), format!(".{name}: {about}")));
            }
            list
        }
        pub(crate) fn complete(
            input: &str,
            cursor: usize,
            src: &dyn Source,
        ) -> Option<Completion> {
            if !input.starts_with('.') || input.starts_with("..")
                || !input.is_char_boundary(cursor) || cursor == 0
            {
                return None;
            }
            let before = &input[1..cursor];
            let toks: Vec<(usize, &str)> = tokens(before)
                .into_iter()
                .map(|(at, w)| (at + 1, w))
                .collect();
            let typing = !before.is_empty() && !before.ends_with(char::is_whitespace);
            let (done, current) = if typing {
                (&toks[..toks.len() - 1], toks.last().copied())
            } else {
                (&toks[..], None)
            };
            let word_start = current.map_or(cursor, |(at, _)| at);
            let mut out = Completion {
                start: word_start,
                end: cursor,
                usage_at: word_start,
                ..Completion::default()
            };
            let Some(((_, name), args)) = done.split_first() else {
                let typed = current.map_or("", |(_, w)| w);
                out.list = matching(command_names(src, typed), typed, false);
                match command(typed) {
                    Some(c) if out.list.is_empty() && !c.usage.is_empty() => {
                        out.usage = Some(format!("{typed} {}", c.usage));
                    }
                    None if out.list.is_empty() && !typed.is_empty()
                        && !plugin(src, typed) => {
                        out.error = Some(format!("Unknown command .{typed}"));
                    }
                    _ => {}
                }
                return Some(out);
            };
            let step = match command(name) {
                Some(c) => {
                    (c
                        .args)(
                        src,
                        &args.iter().map(|(_, w)| *w).collect::<Vec<_>>(),
                        current.map_or("", |(_, w)| w),
                    )
                }
                None if plugin(src, name) => {
                    let about = src
                        .plugin_commands()
                        .into_iter()
                        .find(|(n, _)| n.eq_ignore_ascii_case(name))
                        .map(|(_, a)| a);
                    Step::Free {
                        list: Vec::new(),
                        usage: about.unwrap_or_default(),
                        back: args.len(),
                    }
                }
                None => {
                    out.error = Some(format!("Unknown command .{name}"));
                    out.usage_at = 1;
                    return Some(out);
                }
            };
            let from = |back: usize| {
                if back == 0 || back > args.len() {
                    word_start
                } else {
                    args[args.len() - back].0
                }
            };
            match step {
                Step::Done => {}
                Step::Bad(e) => {
                    out.error = Some(e);
                    out.usage_at = args.first().map_or(word_start, |(at, _)| *at);
                }
                Step::Pick { list, usage, strict, back, ordered } => {
                    out.start = from(back);
                    out.usage_at = out.start;
                    let typed = &input[out.start..cursor];
                    let whole = !typed.trim().is_empty()
                        && list.iter().any(|s| norm(&s.text) == norm(typed));
                    out.list = matching(list, typed, ordered);
                    if out.list.is_empty() && !typed.trim().is_empty() && !whole
                        && let Some(why) = strict
                    {
                        out.error = Some(format!("{why} {}", typed.trim()));
                    }
                    if out.error.is_none() && !whole && !usage.is_empty() {
                        out.usage = Some(usage);
                    }
                }
                Step::Free { list, usage, back } => {
                    out.start = from(back);
                    out.usage_at = out.start;
                    let typed = &input[out.start..cursor];
                    out.list = matching(list, typed, true);
                    if !usage.is_empty() {
                        out.usage = Some(usage);
                    }
                }
            }
            Some(out)
        }
        fn plugin(src: &dyn Source, name: &str) -> bool {
            src.plugin_commands().iter().any(|(n, _)| n.eq_ignore_ascii_case(name))
        }
