    pub(crate) mod sunset_profiles {
        use std::fs::{self, File, OpenOptions};
        use std::io::{Read, Write};
        use std::path::{Path, PathBuf};
        pub(super) const HEADER: &str = "sunset-profile=1";
        pub(super) const BACKUP: &str = "before-load";
        const MAX_BYTES: usize = 1024 * 1024;
        const MAX_PROFILES: usize = 128;
        #[derive(Clone, Debug, Default, PartialEq)]
        pub(super) struct Selection {
            current: Option<(String, u64)>,
            before: Option<(String, u64)>,
            modified: bool,
            pub(super) fresh: bool,
        }
        pub(super) fn fingerprint(text: &str) -> u64 {
            text.bytes()
                .fold(
                    0xcbf29ce484222325,
                    |hash, byte| (hash ^ u64::from(byte)).wrapping_mul(0x100000001b3),
                )
        }
        impl Selection {
            pub(super) fn refresh(&mut self, snapshot: &str) {
                self.modified = self
                    .current
                    .as_ref()
                    .is_some_and(|(_, hash)| *hash != fingerprint(snapshot));
            }
            pub(super) fn selected(&self) -> Option<&str> {
                self.current.as_ref().map(|(name, _)| name.as_str())
            }
            pub(super) fn label(&self) -> String {
                match self.selected() {
                    Some(name) => {
                        format!(
                            "{name}{}", if self.modified { " (modified)" } else { "" }
                        )
                    }
                    None if self.fresh => "Default".into(),
                    None => "Custom".into(),
                }
            }
            pub(super) fn choose(&mut self, name: &str, snapshot: &str) {
                self.current = Some((name.to_owned(), fingerprint(snapshot)));
                self.modified = false;
            }
            pub(super) fn loaded(&mut self, name: &str, snapshot: &str) {
                let previous = self.current.clone();
                if name == BACKUP {
                    self.current = self.before.take();
                } else {
                    self.choose(name, snapshot);
                }
                self.before = previous;
                self.refresh(snapshot);
            }
            pub(super) fn deleted(&mut self, name: &str) {
                if self.selected() == Some(name) {
                    self.current = None;
                    self.modified = false;
                }
                if self.before.as_ref().is_some_and(|(n, _)| n == name) {
                    self.before = None;
                }
            }
            pub(super) fn stored(&self) -> String {
                let encode = |value: &Option<(String, u64)>| {
                    value
                        .as_ref()
                        .map_or(String::new(), |(n, h)| format!("{n}|{h:016x}"))
                };
                format!("{};{}", encode(& self.current), encode(& self.before))
            }
            pub(super) fn restore(&mut self, text: &str) {
                let decode = |value: &str| -> Option<(String, u64)> {
                    let (n, hash) = value.split_once('|')?;
                    (name(n).ok()?.as_str() == n && n != BACKUP && hash.len() == 16)
                        .then(|| {
                            u64::from_str_radix(hash, 16).ok().map(|h| (n.to_owned(), h))
                        })
                        .flatten()
                };
                let (current, before) = text.split_once(';').unwrap_or(("", ""));
                self.current = decode(current);
                self.before = decode(before);
                self.modified = false;
            }
        }
        #[cfg(test)]
        mod selection_tests {
            use super::*;
            #[test]
            fn edits_and_restores_are_tracked() {
                let mut s = Selection::default();
                s.choose("bedwars", "hud.on=true");
                s.refresh("hud.on=false");
                assert_eq!(s.label(), "bedwars (modified)");
                s.refresh("hud.on=true");
                assert_eq!(s.label(), "bedwars");
                let mut none = Selection::default();
                assert_eq!(none.label(), "Custom");
                none.fresh = true;
                assert_eq!(none.label(), "Default");
                s.fresh = true;
                assert_eq!(s.label(), "bedwars");
            }
            #[test]
            fn saved_selection_survives_restart_with_dirty_state() {
                let mut s = Selection::default();
                s.choose("smp", "baseline");
                let mut restored = Selection::default();
                restored.restore(&s.stored());
                restored.refresh("changed");
                assert_eq!(restored.label(), "smp (modified)");
            }
            #[test]
            fn undo_preserves_previous_name_and_dirty_baseline() {
                let mut s = Selection::default();
                s.choose("smp", "baseline");
                s.loaded("bedwars", "new");
                let mut restored = Selection::default();
                restored.restore(&s.stored());
                restored.loaded(BACKUP, "changed");
                assert_eq!(restored.label(), "smp (modified)");
                restored.loaded(BACKUP, "new");
                assert_eq!(restored.label(), "bedwars");
            }
            #[test]
            fn deleting_selected_profile_and_invalid_metadata_show_custom() {
                let mut s = Selection::default();
                s.choose("bedwars", "baseline");
                s.deleted("bedwars");
                assert_eq!(s.label(), "Custom");
                for text in [
                    "../secret|0000000000000000;",
                    "before-load|0000000000000000;",
                    "bedwars|bad;",
                    "broken",
                ] {
                    s.restore(text);
                    assert_eq!(s.label(), "Custom");
                }
            }
        }
        pub(super) fn name(input: &str) -> Result<String, String> {
            let n = input.trim().to_ascii_lowercase().replace(' ', "-");
            let ok = !n.is_empty() && n.len() <= 32
                && n.as_bytes()[0].is_ascii_alphanumeric()
                && n
                    .bytes()
                    .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_');
            if !ok {
                return Err(
                    "a name is 1 to 32 letters, digits, - or _, starting with a letter or digit"
                        .into(),
                );
            }
            let device = |p: &str| {
                n.len() == 4 && n.starts_with(p) && n.as_bytes()[3].is_ascii_digit()
            };
            if matches!(n.as_str(), "con" | "prn" | "aux" | "nul") || device("com")
                || device("lpt")
            {
                return Err(format!("{n} is a name Windows keeps for itself"));
            }
            Ok(n)
        }
        fn linked(m: &fs::Metadata) -> bool {
            #[cfg(windows)]
            {
                use std::os::windows::fs::MetadataExt;
                m.file_attributes() & 0x400 != 0
            }
            #[cfg(not(windows))] { m.file_type().is_symlink() }
        }
        fn plain(path: &Path, directory: bool) -> Result<(), String> {
            let m = fs::symlink_metadata(path)
                .map_err(|e| format!("can't look at {}: {e}", path.display()))?;
            if linked(&m) || m.is_dir() != directory {
                return Err(
                    format!(
                        "{} must be a plain {} (no links)", path.display(), if directory
                        { "folder" } else { "file" }
                    ),
                );
            }
            Ok(())
        }
        fn folder(path: PathBuf) -> Result<PathBuf, String> {
            match fs::create_dir_all(&path) {
                Ok(()) => plain(&path, true).map(|()| path),
                Err(e) => Err(format!("can't make {}: {e}", path.display())),
            }
        }
        pub(super) struct Store {
            profiles: PathBuf,
            exports: PathBuf,
            imports: PathBuf,
        }
        impl Store {
            pub(super) fn new(data: PathBuf) -> Result<Self, String> {
                let data = folder(data)?;
                Ok(Self {
                    profiles: folder(data.join("profiles"))?,
                    exports: folder(data.join("exports"))?,
                    imports: folder(data.join("imports"))?,
                })
            }
            pub(super) fn path(&self, name: &str) -> PathBuf {
                self.profiles.join(format!("{name}.profile"))
            }
            pub(super) fn exists(&self, name: &str) -> bool {
                self.path(name).is_file()
            }
            pub(super) fn read(&self, name: &str) -> Result<String, String> {
                read(&self.path(name))
            }
            pub(super) fn list(&self) -> Result<Vec<String>, String> {
                let mut names = Vec::new();
                for entry in fs::read_dir(&self.profiles)
                    .map_err(|e| format!("can't list the profiles: {e}"))?
                    .flatten()
                {
                    let file = entry.file_name();
                    if let Some(n) = file
                        .to_str()
                        .and_then(|f| f.strip_suffix(".profile"))
                        && name(n).as_deref() == Ok(n) && n != BACKUP
                    {
                        names.push(n.to_owned());
                    }
                }
                names.sort();
                Ok(names)
            }
            pub(super) fn write(&self, name: &str, text: &str) -> Result<(), String> {
                if name != BACKUP && !self.exists(name)
                    && self.list()?.len() >= MAX_PROFILES
                {
                    return Err(
                        format!("{MAX_PROFILES} profiles are the most; delete one first"),
                    );
                }
                write(&self.path(name), text)
            }
            pub(super) fn delete(&self, name: &str) -> Result<(), String> {
                let path = self.path(name);
                plain(&path, false)?;
                fs::remove_file(&path).map_err(|e| format!("can't delete {name}: {e}"))
            }
            pub(super) fn export(&self, name: &str) -> Result<PathBuf, String> {
                let to = self.exports.join(format!("{name}.profile"));
                write(&to, &self.read(name)?)?;
                Ok(to)
            }
            pub(super) fn import(&self, name: &str) -> Result<String, String> {
                read(&self.imports.join(format!("{name}.profile")))
            }
            pub(super) fn share(
                &self,
                file: &str,
                text: &str,
            ) -> Result<PathBuf, String> {
                let to = self.exports.join(file);
                write(&to, text)?;
                Ok(to)
            }
            pub(super) fn shared(&self, file: &str) -> Result<String, String> {
                read(&self.imports.join(file))
            }
            pub(super) fn imports(&self) -> &Path {
                &self.imports
            }
            pub(super) fn import_names(&self) -> Vec<String> {
                let mut found: Vec<String> = fs::read_dir(&self.imports)
                    .map(|dir| {
                        dir.flatten()
                            .filter_map(|e| {
                                e.file_name()
                                    .to_str()
                                    .and_then(|f| f.strip_suffix(".profile"))
                                    .map(str::to_owned)
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                found.sort();
                found
            }
        }
        fn read(path: &Path) -> Result<String, String> {
            plain(path, false)?;
            let mut bytes = Vec::new();
            File::open(path)
                .and_then(|f| f.take(MAX_BYTES as u64 + 1).read_to_end(&mut bytes))
                .map_err(|e| format!("can't read {}: {e}", path.display()))?;
            if bytes.len() > MAX_BYTES {
                return Err("a profile is 1 MiB at most".into());
            }
            String::from_utf8(bytes).map_err(|_| "a profile is UTF-8 text".into())
        }
        pub(super) fn write_config(
            data: &Path,
            key: &str,
            text: &str,
        ) -> Result<(), String> {
            let data = folder(data.to_path_buf())?;
            write_limited(&data.join(key), text, 16 * MAX_BYTES)
        }
        pub(super) fn outside(path: &Path) -> Result<(String, String), String> {
            Ok((outside_name(path)?, read(path)?))
        }
        pub(super) fn outside_name(path: &Path) -> Result<String, String> {
            let stem = path
                .file_name()
                .and_then(|f| f.to_str())
                .and_then(|f| f.rsplit_once('.'))
                .filter(|(_, ext)| ext.eq_ignore_ascii_case("profile"))
                .map(|(stem, _)| stem)
                .ok_or_else(|| format!("{} is not a .profile file", path.display()))?;
            let plain: String = stem
                .chars()
                .map(|c| {
                    if c.is_ascii_alphanumeric() || c == '_' {
                        c.to_ascii_lowercase()
                    } else {
                        '-'
                    }
                })
                .collect();
            let plain: String = plain
                .trim_matches(['-', '_'])
                .chars()
                .take(28)
                .collect();
            Ok(
                name(&plain)
                    .ok()
                    .filter(|n| n != BACKUP)
                    .unwrap_or_else(|| "imported".to_owned()),
            )
        }
        static CHOOSING: std::sync::Mutex<
            Option<std::sync::mpsc::Receiver<Option<Vec<PathBuf>>>>,
        > = std::sync::Mutex::new(None);
        pub(super) fn choose() -> bool {
            let mut waiting = CHOOSING.lock().unwrap_or_else(|e| e.into_inner());
            if waiting.is_some() {
                return false;
            }
            let (tx, rx) = std::sync::mpsc::channel();
            let started = std::thread::Builder::new()
                .name("sunset-file-chooser".into())
                .spawn(move || {
                    let _ = tx.send(choose_files());
                });
            drop(started);
            *waiting = Some(rx);
            true
        }
        pub(super) fn chosen() -> Option<Option<Vec<PathBuf>>> {
            use std::sync::mpsc::TryRecvError;
            let mut waiting = CHOOSING.lock().unwrap_or_else(|e| e.into_inner());
            let answer = match waiting.as_ref()?.try_recv() {
                Ok(files) => files,
                Err(TryRecvError::Empty) => return None,
                Err(TryRecvError::Disconnected) => None,
            };
            *waiting = None;
            Some(answer)
        }
        fn choose_files() -> Option<Vec<PathBuf>> {
            use std::ffi::OsStr;
            use std::process::{Command, Stdio};
            fn run(program: &OsStr, args: &[&str]) -> Option<Vec<PathBuf>> {
                let mut c = Command::new(program);
                c.args(args).stdin(Stdio::null()).stderr(Stdio::null());
                #[cfg(windows)]
                std::os::windows::process::CommandExt::creation_flags(
                    &mut c,
                    0x0800_0000,
                );
                let out = c.output().ok()?;
                Some(
                    String::from_utf8_lossy(&out.stdout)
                        .lines()
                        .map(str::trim)
                        .filter(|l| !l.is_empty())
                        .map(PathBuf::from)
                        .collect(),
                )
            }
            const TITLE: &str = "Import Sunset profiles";
            if let Some(own) = std::env::var_os("SUNSET_FILE_CHOOSER")
                .filter(|p| !p.is_empty())
            {
                return run(&own, &[]);
            }
            if cfg!(windows) {
                let script = "[Console]::OutputEncoding = [Text.Encoding]::UTF8; Add-Type -AssemblyName System.Windows.Forms; \
            $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Title = 'Import Sunset profiles'; \
            $d.Filter = 'Sunset profiles (*.profile)|*.profile|All files (*.*)|*.*'; $d.Multiselect = $true; \
            if ($d.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $d.FileNames | ForEach-Object { [Console]::Out.WriteLine($_) } }";
                run(
                    OsStr::new("powershell"),
                    &["-NoProfile", "-STA", "-Command", script],
                )
            } else if cfg!(target_os = "macos") {
                run(
                    OsStr::new("osascript"),
                    &[
                        "-e",
                        "set picked to choose file with prompt \"Import Sunset profiles\" with multiple selections allowed",
                        "-e",
                        "set out to \"\"",
                        "-e",
                        "repeat with f in picked",
                        "-e",
                        "set out to out & POSIX path of f & linefeed",
                        "-e",
                        "end repeat",
                        "-e",
                        "return out",
                    ],
                )
            } else {
                let title = format!("--title={TITLE}");
                run(
                        OsStr::new("zenity"),
                        &[
                            "--file-selection",
                            "--multiple",
                            "--separator=\n",
                            &title,
                            "--file-filter=Sunset profiles (*.profile) | *.profile",
                            "--file-filter=All files | *",
                        ],
                    )
                    .or_else(|| run(
                        OsStr::new("kdialog"),
                        &[
                            "--title",
                            TITLE,
                            "--multiple",
                            "--separate-output",
                            "--getopenfilename",
                            ".",
                            "Sunset profiles (*.profile)",
                        ],
                    ))
            }
        }
        pub(super) fn write_in_place(
            data: &Path,
            key: &str,
            text: &str,
        ) -> Result<(), String> {
            let path = folder(data.to_path_buf())?.join(key);
            if fs::symlink_metadata(&path).is_ok() {
                plain(&path, false)?;
            }
            fs::write(&path, text)
                .map_err(|e| format!("can't write {}: {e}", path.display()))
        }
        pub(super) fn kept(data: &Path, key: &str) -> Option<String> {
            read(&own(data, key)?).ok().map(|text| text.trim().to_owned())
        }
        pub(super) fn keep(data: &Path, key: &str, text: &str) -> Result<(), String> {
            if own(data, key).is_none() {
                return Err(format!("\"{key}\" is not a file name"));
            }
            write_config(data, key, text)
        }
        fn own(data: &Path, key: &str) -> Option<PathBuf> {
            let mut parts = Path::new(key).components();
            matches!(
                (parts.next(), parts.next()), (Some(std::path::Component::Normal(_)),
                None)
            )
                .then(|| data.join(key))
        }
        pub(super) fn whole_config(text: &str) -> bool {
            text.lines().any(|l| l.contains(".on="))
        }
        pub(super) fn sweep(data: &Path) {
            for dir in [data.to_path_buf(), data.join("profiles")] {
                for entry in fs::read_dir(&dir).into_iter().flatten().flatten() {
                    let name = entry.file_name();
                    let Some(name) = name.to_str() else { continue };
                    let stray = name
                        .rsplit_once(".tmp")
                        .is_some_and(|(_, pid)| {
                            !pid.is_empty() && pid.bytes().all(|b| b.is_ascii_digit())
                        });
                    if stray && entry.file_type().is_ok_and(|t| t.is_file()) {
                        let _ = fs::remove_file(entry.path());
                    }
                }
            }
        }
        fn write(path: &Path, text: &str) -> Result<(), String> {
            write_limited(path, text, MAX_BYTES)
        }
        fn write_limited(path: &Path, text: &str, limit: usize) -> Result<(), String> {
            if text.len() > limit {
                return Err(
                    format!("{} is {} KiB at most", path.display(), limit / 1024),
                );
            }
            if fs::symlink_metadata(path).is_ok() {
                plain(path, false)?;
            }
            let tmp = path.with_extension(format!("tmp{}", std::process::id()));
            let done = OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&tmp)
                .and_then(|mut f| {
                    f.write_all(text.as_bytes()).and_then(|()| f.sync_all())
                })
                .and_then(|()| fs::rename(&tmp, path));
            if done.is_err() {
                let _ = fs::remove_file(&tmp);
            }
            done.map_err(|e| format!("can't write {}: {e}", path.display()))
        }
        #[cfg(test)]
        mod store_tests {
            use super::*;
            #[test]
            fn config_writes_replace_whole_and_leftovers_are_swept() {
                let dir = std::env::temp_dir()
                    .join(format!("sunset-store-test-{}", std::process::id()));
                let _ = fs::remove_dir_all(&dir);
                write_config(&dir, "config", "sprint.on=true\n").unwrap();
                write_config(&dir, "config", "sprint.on=false\nhud.on=true\n").unwrap();
                assert_eq!(
                    fs::read_to_string(dir.join("config")).unwrap(),
                    "sprint.on=false\nhud.on=true\n"
                );
                fs::write(dir.join("config.tmp4242"), "half").unwrap();
                fs::create_dir_all(dir.join("profiles")).unwrap();
                fs::write(dir.join("profiles").join("pvp.tmp99"), "half").unwrap();
                fs::write(dir.join("profiles").join("pvp.profile"), "kept").unwrap();
                sweep(&dir);
                assert!(
                    ! dir.join("config.tmp4242").exists() && ! dir.join("profiles")
                    .join("pvp.tmp99").exists()
                );
                assert!(
                    dir.join("profiles").join("pvp.profile").exists() && dir
                    .join("config").exists()
                );
                assert!(
                    whole_config("sprint.on=true") && ! whole_config("") && !
                    whole_config("friends=a")
                );
                let _ = fs::remove_dir_all(&dir);
            }
            #[test]
            fn outside_files_get_profile_names() {
                let named = |file: &str| outside_name(Path::new(file));
                assert_eq!(
                    named("/home/a/Sword PvP (v2).profile").as_deref(),
                    Ok("sword-pvp--v2")
                );
                assert_eq!(
                    named("C:\\Users\\a\\Downloads\\crystal.PROFILE").map(| n | n
                    .ends_with("crystal")), Ok(true)
                );
                assert_eq!(named("x/__.profile").as_deref(), Ok("imported"));
                assert_eq!(named("x/con.profile").as_deref(), Ok("imported"));
                assert_eq!(named("x/before-load.profile").as_deref(), Ok("imported"));
                assert_eq!(
                    named("x/a-very-long-name-that-goes-on-and-on-and-on.profile").map(|
                    n | n.len()), Ok(28)
                );
                assert!(
                    named("x/notes.txt").is_err() && named("x/profile").is_err() &&
                    named("x/").is_err()
                );
                let dir = std::env::temp_dir()
                    .join(format!("sunset-outside-test-{}", std::process::id()));
                let _ = fs::remove_dir_all(&dir);
                fs::create_dir_all(&dir).unwrap();
                fs::write(
                        dir.join("Duels 1.profile"),
                        "sunset-profile=1\nsprint.on=true\n",
                    )
                    .unwrap();
                assert_eq!(
                    outside(& dir.join("Duels 1.profile")), Ok(("duels-1".to_owned(),
                    "sunset-profile=1\nsprint.on=true\n".to_owned()))
                );
                assert!(outside(& dir.join("missing.profile")).is_err());
                let _ = fs::remove_dir_all(&dir);
            }
            #[test]
            fn own_files_are_kept_and_read_by_plain_names_only() {
                let dir = std::env::temp_dir()
                    .join(format!("sunset-kept-test-{}", std::process::id()));
                let _ = fs::remove_dir_all(&dir);
                assert_eq!(kept(& dir, "presence-notice-2"), None);
                keep(&dir, "presence-notice-2", "1").unwrap();
                assert_eq!(kept(& dir, "presence-notice-2").as_deref(), Some("1"));
                keep(&dir, "xray-placed-00000000000000ab", " 1,2,3;4,5,6\n").unwrap();
                assert_eq!(
                    kept(& dir, "xray-placed-00000000000000ab").as_deref(),
                    Some("1,2,3;4,5,6")
                );
                keep(&dir, "xray-placed-00000000000000ab", "").unwrap();
                assert_eq!(
                    kept(& dir, "xray-placed-00000000000000ab").as_deref(), Some("")
                );
                fs::create_dir_all(dir.join("profiles")).unwrap();
                assert_eq!(kept(& dir, "profiles"), None);
                fs::write(dir.join("profiles").join("pvp.profile"), "x").unwrap();
                for out in [
                    "profiles/pvp.profile",
                    "../outside",
                    "",
                    ".",
                    "..",
                    "/etc/hostname",
                ] {
                    assert_eq!(kept(& dir, out), None, "{out}");
                    assert!(keep(& dir, out, "x").is_err(), "{out}");
                }
                assert!(! dir.parent().unwrap().join("outside").exists());
                write_in_place(&dir, "config", "sprint.on=true\n").unwrap();
                write_in_place(&dir, "config", "sprint.on=false\n").unwrap();
                assert_eq!(kept(& dir, "config").as_deref(), Some("sprint.on=false"));
                assert!(write_in_place(& dir, "profiles", "x").is_err());
                let _ = fs::remove_dir_all(&dir);
            }
        }
    }
    pub(crate) mod sunset_profile_menu {
        use crate::game::sunset_compat::SunsetGame as _;
        use super::{Game, sunset::{Shape, accent, panel_radius}};
        use super::sunset_presets::PRESETS;
        const ROW: f32 = 18.0;
        const TOP: f32 = 25.0;
        const BOTTOM: f32 = 22.0;
        const LINE: f32 = 11.0;
        const BUTTONS: f32 = 30.0;
        #[derive(Clone, Copy, Debug, PartialEq)]
        pub(super) enum Tab {
            Saved,
            Presets,
            Import,
        }
        pub(super) enum Choice {
            Load(String),
            Save(String),
            Preview(usize),
            Apply(usize),
            Import(String),
            ImportAs(String, bool),
            Paste,
        }
        #[derive(Clone, Debug)]
        pub(super) struct Preview {
            pub(super) preset: usize,
            pub(super) lines: Vec<(String, u32)>,
        }
        #[derive(Clone, Debug)]
        pub(super) struct Menu {
            pub(super) names: Vec<String>,
            imports: Vec<String>,
            pub(super) error: Option<String>,
            note: Option<String>,
            pub(super) ask: Option<String>,
            pub(super) ask_file: Option<std::path::PathBuf>,
            pub(super) tab: Tab,
            pub(super) preview: Option<Preview>,
            in_use: Option<String>,
            focus: usize,
            start: usize,
        }
        pub(super) fn width(w: f32) -> f32 {
            (w - 16.0).min(300.0)
        }
        fn frame(w: f32, h: f32, count: usize) -> [f32; 4] {
            let ww = width(w);
            let hh = (count.clamp(1, 10) as f32 * ROW + TOP + BOTTOM).min(h - 16.0);
            [(w - ww) / 2.0, (h - hh) / 2.0, ww, hh]
        }
        fn preview_frame(w: f32, h: f32, lines: usize) -> [f32; 4] {
            let ww = width(w);
            let hh = (lines as f32 * LINE + TOP + BUTTONS + 6.0).min(h - 16.0);
            [(w - ww) / 2.0, (h - hh) / 2.0, ww, hh]
        }
        fn preview_rows(r: [f32; 4]) -> usize {
            ((r[3] - TOP - BUTTONS - 6.0) / LINE).max(1.0) as usize
        }
        fn buttons(r: [f32; 4]) -> ([f32; 4], [f32; 4]) {
            let (bw, bh) = (60.0, 16.0);
            let y = r[1] + r[3] - bh - 8.0;
            (
                [r[0] + r[2] - 2.0 * bw - 14.0, y, bw, bh],
                [r[0] + r[2] - bw - 8.0, y, bw, bh],
            )
        }
        fn save_button(r: [f32; 4]) -> [f32; 4] {
            [r[0] + r[2] - 98.0, r[1] + r[3] - 19.0, 90.0, 15.0]
        }
        fn paste_button(r: [f32; 4]) -> [f32; 4] {
            [r[0] + r[2] - 118.0, r[1] + r[3] - 19.0, 110.0, 15.0]
        }
        fn ask_buttons(r: [f32; 4]) -> ([f32; 4], [f32; 4]) {
            let y = r[1] + r[3] - 19.0;
            ([r[0] + r[2] - 132.0, y, 64.0, 15.0], [r[0] + r[2] - 64.0, y, 56.0, 15.0])
        }
        fn tabs(r: [f32; 4]) -> [([f32; 4], Tab, &'static str); 3] {
            let (x, y) = (r[0] + r[2], r[1] + 4.0);
            [
                ([x - 190.0, y, 50.0, 15.0], Tab::Saved, "Saved"),
                ([x - 138.0, y, 56.0, 15.0], Tab::Presets, "Presets"),
                ([x - 80.0, y, 52.0, 15.0], Tab::Import, "Import"),
            ]
        }
        fn rows(r: [f32; 4]) -> usize {
            ((r[3] - TOP - BOTTOM) / ROW).max(1.0) as usize
        }
        fn inside(r: [f32; 4], at: (f32, f32)) -> bool {
            at.0 >= r[0] && at.0 < r[0] + r[2] && at.1 >= r[1] && at.1 < r[1] + r[3]
        }
        impl Menu {
            pub(super) fn new(
                names: Vec<String>,
                imports: Vec<String>,
                selected: Option<&str>,
                w: f32,
                h: f32,
            ) -> Self {
                let tab = if names.is_empty() { Tab::Presets } else { Tab::Saved };
                let focus = selected
                    .and_then(|n| names.iter().position(|p| p == n))
                    .unwrap_or(0);
                let in_use = selected
                    .filter(|n| names.iter().any(|p| p == n))
                    .map(str::to_owned);
                let mut menu = Self {
                    names,
                    imports,
                    error: None,
                    note: None,
                    ask: None,
                    ask_file: None,
                    tab,
                    preview: None,
                    in_use,
                    focus,
                    start: 0,
                };
                menu.reveal(w, h);
                menu
            }
            fn count(&self) -> usize {
                match self.tab {
                    Tab::Saved => self.names.len(),
                    Tab::Presets => PRESETS.len(),
                    Tab::Import => self.imports.len(),
                }
            }
            fn list_frame(&self, w: f32, h: f32) -> [f32; 4] {
                frame(
                    w,
                    h,
                    self.names.len().max(PRESETS.len()).max(self.imports.len().max(2)),
                )
            }
            fn rect(&self, w: f32, h: f32) -> [f32; 4] {
                match &self.preview {
                    Some(p) => preview_frame(w, h, p.lines.len()),
                    None => self.list_frame(w, h),
                }
            }
            fn reveal(&mut self, w: f32, h: f32) {
                let count = rows(self.list_frame(w, h));
                self.start = self
                    .start
                    .min(self.focus)
                    .max((self.focus + 1).saturating_sub(count));
            }
            fn switch(&mut self, tab: Tab, w: f32, h: f32) {
                if self.tab != tab {
                    self.tab = tab;
                    self.focus = 0;
                    self.start = 0;
                    self.error = None;
                    self.note = None;
                    self.ask = None;
                    self.ask_file = None;
                    self.reveal(w, h);
                }
            }
            pub(super) fn asks(
                &mut self,
                name: String,
                file: Option<std::path::PathBuf>,
                w: f32,
                h: f32,
            ) {
                self.preview = None;
                self.switch(Tab::Import, w, h);
                self.error = None;
                self.note = None;
                self.ask = Some(name);
                self.ask_file = file;
            }
            pub(super) fn took(
                &mut self,
                names: Vec<String>,
                landed: Option<&str>,
                note: String,
                w: f32,
                h: f32,
            ) {
                self.names = names;
                self.tab = Tab::Saved;
                self.focus = landed
                    .and_then(|n| self.names.iter().position(|p| p == n))
                    .unwrap_or(0);
                self.start = 0;
                self.error = None;
                self.ask = None;
                self.ask_file = None;
                self.note = Some(note);
                self.reveal(w, h);
            }
            fn choice(&self, i: usize) -> Option<Choice> {
                match self.tab {
                    Tab::Saved => self.names.get(i).cloned().map(Choice::Load),
                    Tab::Presets => (i < PRESETS.len()).then_some(Choice::Preview(i)),
                    Tab::Import => self.imports.get(i).cloned().map(Choice::Import),
                }
            }
            pub(super) fn scroll(&mut self, steps: i32, w: f32, h: f32) {
                if self.preview.is_some() {
                    return;
                }
                let max = self.count().saturating_sub(rows(self.list_frame(w, h)));
                self.start = (self.start as i32 + steps).clamp(0, max as i32) as usize;
            }
            pub(super) fn back(&mut self) -> bool {
                self.error = None;
                self.ask_file = None;
                self.ask.take().is_some() || self.preview.take().is_some()
            }
            pub(super) fn key(&mut self, key: &str, w: f32, h: f32) -> Option<Choice> {
                let enter = matches!(
                    key, "key.keyboard.enter" | "key.keyboard.numpad.enter"
                );
                if let Some(p) = &self.preview {
                    return enter.then_some(Choice::Apply(p.preset));
                }
                match key {
                    "key.keyboard.up" => self.focus = self.focus.saturating_sub(1),
                    "key.keyboard.down" => {
                        self.focus = (self.focus + 1)
                            .min(self.count().saturating_sub(1));
                    }
                    "key.keyboard.left" => {
                        self.switch(
                            if self.tab == Tab::Import {
                                Tab::Presets
                            } else {
                                Tab::Saved
                            },
                            w,
                            h,
                        )
                    }
                    "key.keyboard.right" => {
                        self.switch(
                            if self.tab == Tab::Saved {
                                Tab::Presets
                            } else {
                                Tab::Import
                            },
                            w,
                            h,
                        )
                    }
                    _ if enter => return self.choice(self.focus),
                    _ => return None,
                }
                self.reveal(w, h);
                None
            }
            pub(super) fn click(
                &mut self,
                at: (f32, f32),
                w: f32,
                h: f32,
            ) -> Option<Choice> {
                let r = self.rect(w, h);
                if let Some(p) = &self.preview {
                    let (apply, back) = buttons(r);
                    if inside(apply, at) {
                        return Some(Choice::Apply(p.preset));
                    }
                    if inside(back, at) {
                        self.back();
                    }
                    return None;
                }
                if let Some((_, tab, _)) = tabs(r)
                    .into_iter()
                    .find(|(t, _, _)| inside(*t, at))
                {
                    self.switch(tab, w, h);
                    return None;
                }
                if self.tab == Tab::Saved && let Some(name) = &self.in_use
                    && inside(save_button(r), at)
                {
                    return Some(Choice::Save(name.clone()));
                }
                if self.tab == Tab::Import {
                    if let Some(name) = &self.ask {
                        let (keep, replace) = ask_buttons(r);
                        if inside(keep, at) || inside(replace, at) {
                            return Some(
                                Choice::ImportAs(name.clone(), inside(replace, at)),
                            );
                        }
                    } else if inside(paste_button(r), at) {
                        return Some(Choice::Paste);
                    }
                }
                let list = [r[0] + 4.0, r[1] + TOP, r[2] - 8.0, rows(r) as f32 * ROW];
                inside(list, at)
                    .then(|| self.choice(self.start + ((at.1 - list[1]) / ROW) as usize))
                    .flatten()
            }
            pub(super) fn closes(&self, at: (f32, f32), w: f32, h: f32) -> bool {
                let r = self.rect(w, h);
                !inside(r, at) || inside([r[0] + r[2] - 25.0, r[1], 25.0, 22.0], at)
            }
        }
        fn fit(game: &Game<'_>, text: &str, width: f32) -> String {
            super::sunset::fit_to(game, text, width)
        }
        pub(super) fn preview_lines(
            game: &Game<'_>,
            w: f32,
            preset: usize,
            lines: &[String],
        ) -> Vec<(String, u32)> {
            let room = width(w) - 16.0;
            let about = super::sunset::wrap(game, PRESETS[preset].about, room);
            let mut out: Vec<(String, u32)> = about
                .into_iter()
                .map(|l| (l, 0x909090))
                .collect();
            for line in lines {
                let colour = if line.starts_with("Turns on") {
                    accent()
                } else if line.starts_with("Turns off") {
                    0xFF9090
                } else {
                    0xFFFFFF
                };
                out.extend(
                    super::sunset::wrap(game, line, room)
                        .into_iter()
                        .map(|l| (l, colour)),
                );
            }
            out
        }
        pub(super) fn draw(
            game: &Game<'_>,
            w: f32,
            h: f32,
            at: (f32, f32),
            selected: Option<&str>,
            in_use: &str,
            menu: Option<&Menu>,
            out: &mut Vec<Shape>,
        ) {
            let Some(menu) = menu else {
                return;
            };
            let r = menu.rect(w, h);
            out.push(Shape::Fill([0.0, 0.0, w, h], 0x8000_0000));
            super::sunset::framed(
                out,
                r,
                panel_radius(),
                super::sunset::pal().profile_panel,
                1.0,
            );
            let close = [r[0] + r[2] - 25.0, r[1], 25.0, 22.0];
            super::sunset::cross(out, close, inside(close, at));
            if let Some(p) = &menu.preview {
                out.push(
                    Shape::Head(
                        fit(game, PRESETS[p.preset].title, r[2] - 40.0),
                        [r[0] + 8.0, r[1] + 7.0],
                        0xFFFFFF,
                    ),
                );
                let fits = preview_rows(r);
                for (n, (line, colour)) in p.lines.iter().take(fits).enumerate() {
                    let text = if n + 1 == fits && p.lines.len() > fits {
                        format!("{line} ...")
                    } else {
                        line.clone()
                    };
                    out.push(
                        Shape::Text(
                            fit(game, &text, r[2] - 16.0),
                            [r[0] + 8.0, r[1] + TOP + n as f32 * LINE],
                            *colour,
                        ),
                    );
                }
                let (apply, back) = buttons(r);
                for (b, label, colour) in [
                    (apply, "Apply", 0xFF00_0000 | accent()),
                    (back, "Back", super::sunset::pal().button),
                ] {
                    out.push(Shape::Round(b, panel_radius(), colour));
                    let tw = game.sunset_text_width(label);
                    out.push(
                        Shape::Text(
                            label.to_owned(),
                            [
                                b[0] + (b[2] - tw) / 2.0,
                                b[1] + super::sunset::text_y(b[3]),
                            ],
                            0xFFFFFF,
                        ),
                    );
                }
                if let Some(error) = &menu.error {
                    out.push(
                        Shape::Text(
                            fit(game, error, r[2] - 150.0),
                            [r[0] + 8.0, r[1] + r[3] - 20.0],
                            0xFF9090,
                        ),
                    );
                }
                return;
            }
            out.push(Shape::Head("Profiles".into(), [r[0] + 8.0, r[1] + 7.0], 0xFFFFFF));
            for (t, tab, label) in tabs(r) {
                let tw = game.sunset_text_width(label);
                let text_at = [t[0] + (t[2] - tw) / 2.0, t[1] + 3.0];
                if menu.tab == tab {
                    out.push(Shape::Round(t, panel_radius(), 0xFF00_0000 | accent()));
                    out.push(Shape::Plain(label.to_owned(), text_at, 0xFFFFFF, false));
                } else {
                    out.push(
                        Shape::Text(
                            label.to_owned(),
                            text_at,
                            if inside(t, at) { 0xD4D4D8 } else { 0x909090 },
                        ),
                    );
                }
            }
            if menu.tab == Tab::Saved && menu.names.is_empty() {
                out.push(
                    Shape::Text(
                        "None saved yet: .profile save <name>".into(),
                        [r[0] + 8.0, r[1] + TOP + 5.0],
                        0xFFFFFF,
                    ),
                );
            }
            if menu.tab == Tab::Import && menu.imports.is_empty() {
                out.push(
                    Shape::Text(
                        fit(
                            game,
                            "No files waiting. Drop .profile files on this menu,",
                            r[2] - 16.0,
                        ),
                        [r[0] + 8.0, r[1] + TOP + 5.0],
                        0xFFFFFF,
                    ),
                );
                out.push(
                    Shape::Text(
                        fit(
                            game,
                            "or type .profile import to choose them.",
                            r[2] - 16.0,
                        ),
                        [r[0] + 8.0, r[1] + TOP + 5.0 + LINE],
                        0xFFFFFF,
                    ),
                );
            }
            for i in (menu.start..menu.count()).take(rows(r)) {
                let row = [
                    r[0] + 4.0,
                    r[1] + TOP + (i - menu.start) as f32 * ROW,
                    r[2] - 8.0,
                    ROW,
                ];
                if inside(row, at) || i == menu.focus {
                    out.push(
                        Shape::Round(
                            row,
                            panel_radius(),
                            super::sunset::pal().profile_tab,
                        ),
                    );
                }
                let at_text = [row[0] + 5.0, row[1] + 5.0];
                match menu.tab {
                    Tab::Saved => {
                        let name = &menu.names[i];
                        let colour = if selected == Some(name.as_str()) {
                            accent()
                        } else {
                            0xFFFFFF
                        };
                        out.push(
                            Shape::Text(fit(game, name, row[2] - 10.0), at_text, colour),
                        );
                    }
                    Tab::Presets => {
                        let preset = &PRESETS[i];
                        let colour = if selected == Some(preset.id) {
                            accent()
                        } else {
                            0xFFFFFF
                        };
                        let title = fit(game, preset.title, row[2] - 10.0);
                        let tw = game.sunset_text_width(&title);
                        out.push(Shape::Text(title, at_text, colour));
                        let room = row[2] - 18.0 - tw;
                        if room > 30.0 {
                            out.push(
                                Shape::Text(
                                    fit(game, preset.about, room),
                                    [at_text[0] + tw + 8.0, at_text[1]],
                                    0x808080,
                                ),
                            );
                        }
                    }
                    Tab::Import => {
                        out.push(
                            Shape::Text(
                                fit(game, &menu.imports[i], row[2] - 10.0),
                                at_text,
                                0xFFFFFF,
                            ),
                        )
                    }
                }
            }
            let button = |out: &mut Vec<Shape>, b: [f32; 4], label: &str| {
                out.push(
                    Shape::Round(
                        b,
                        panel_radius(),
                        if inside(b, at) {
                            0xFF00_0000 | accent()
                        } else {
                            super::sunset::pal().button
                        },
                    ),
                );
                let tw = game.sunset_text_width(label);
                out.push(
                    Shape::Text(
                        label.to_owned(),
                        [b[0] + (b[2] - tw) / 2.0, b[1] + 3.0],
                        0xFFFFFF,
                    ),
                );
            };
            let mut taken = 8.0;
            if menu.tab == Tab::Import {
                if let Some(name) = &menu.ask {
                    let (keep, replace) = ask_buttons(r);
                    button(out, keep, "Keep both");
                    button(out, replace, "Replace");
                    let said = fit(
                        game,
                        &format!("{name} is saved already."),
                        keep[0] - r[0] - 14.0,
                    );
                    out.push(
                        Shape::Text(said, [r[0] + 8.0, r[1] + r[3] - 16.0], 0xFFFFFF),
                    );
                    return;
                }
                let b = paste_button(r);
                button(out, b, "Paste from clipboard");
                taken = b[2] + 14.0;
            }
            let saving = menu.tab == Tab::Saved && menu.in_use.is_some();
            if let Some(name) = menu.in_use.as_deref().filter(|_| saving) {
                let b = save_button(r);
                out.push(
                    Shape::Round(
                        b,
                        panel_radius(),
                        if inside(b, at) {
                            0xFF00_0000 | accent()
                        } else {
                            super::sunset::pal().button
                        },
                    ),
                );
                let label = fit(game, &format!("Save {name}"), b[2] - 8.0);
                let tw = game.sunset_text_width(&label);
                out.push(
                    Shape::Text(label, [b[0] + (b[2] - tw) / 2.0, b[1] + 3.0], 0xFFFFFF),
                );
            }
            let room = r[2] - 8.0 - if saving { 104.0 } else { taken };
            if let Some(error) = &menu.error {
                out.push(
                    Shape::Text(
                        fit(game, error, room),
                        [r[0] + 8.0, r[1] + r[3] - 16.0],
                        0xFF9090,
                    ),
                );
            } else if let Some(note) = &menu.note {
                out.push(
                    Shape::Text(
                        fit(game, note, room),
                        [r[0] + 8.0, r[1] + r[3] - 16.0],
                        0xC8C8C8,
                    ),
                );
            } else if menu.tab != Tab::Import {
                let said = match (menu.tab, menu.names.is_empty()) {
                    (Tab::Presets, _) => {
                        format!(
                            "In use: {in_use}. Click a preset to see what it changes."
                        )
                    }
                    (_, true) => format!("In use: {in_use}."),
                    (_, false) => {
                        format!("In use: {in_use}. Click a profile to load it.")
                    }
                };
                out.push(
                    Shape::Text(
                        fit(game, &said, room),
                        [r[0] + 8.0, r[1] + r[3] - 16.0],
                        0x909090,
                    ),
                );
            }
        }
    }
