        struct Task {
            id: u64,
            plugin: Option<&'static str>,
            due: u64,
            every: Option<u64>,
            run: Run,
        }
        static TASKS: Mutex<Vec<Task>> = Mutex::new(Vec::new());
        static CANCELLED: Mutex<Vec<u64>> = Mutex::new(Vec::new());
        static NEXT_TASK: AtomicU64 = AtomicU64::new(1);
        static CLOCK: AtomicU64 = AtomicU64::new(0);
        fn schedule(ticks: u64, every: Option<u64>, run: Run) -> u64 {
            let mut tasks = lock(&TASKS);
            if !RUNTIME.running() {
                return 0;
            }
            let id = NEXT_TASK.fetch_add(1, Ordering::Relaxed);
            let plugin = CURRENT.with(Cell::get);
            let due = CLOCK.load(Ordering::Relaxed) + ticks.max(1);
            tasks
                .push(Task {
                    id,
                    plugin,
                    due,
                    every,
                    run,
                });
            id
        }
        #[allow(dead_code)]
        pub(super) fn after(
            ticks: u64,
            f: impl for<'a, 'b> FnOnce(&'a mut Game<'b>) + Send + 'static,
        ) -> u64 {
            let mut f = Some(f);
            schedule(
                ticks,
                None,
                Box::new(move |game| {
                    if let Some(f) = f.take() {
                        f(game);
                    }
                }),
            )
        }
        #[allow(dead_code)]
        pub(super) fn every(
            ticks: u64,
            f: impl for<'a, 'b> FnMut(&'a mut Game<'b>) + Send + 'static,
        ) -> u64 {
            schedule(ticks, Some(ticks.max(1)), Box::new(f))
        }
        #[allow(dead_code)]
        pub(super) fn cancel(id: u64) -> bool {
            let mut tasks = lock(&TASKS);
            let before = tasks.len();
            tasks.retain(|t| t.id != id);
            if tasks.len() != before {
                return true;
            }
            drop(tasks);
            lock(&CANCELLED).push(id);
            false
        }
        #[allow(dead_code)]
        pub(super) fn tasks() -> usize {
            lock(&TASKS).len()
        }
        pub(super) fn cancel_tasks() {
            let tasks = std::mem::take(&mut *lock(&TASKS));
            drop(tasks);
            lock(&CANCELLED).clear();
        }
        fn run_tasks(game: &mut Game<'_>) {
            let generation = RUNTIME.token();
            if !RUNTIME.current(generation) {
                return;
            }
            let now = CLOCK.fetch_add(1, Ordering::Relaxed) + 1;
            let due: Vec<Task> = {
                let mut tasks = lock(&TASKS);
                let (due, wait) = std::mem::take(&mut *tasks)
                    .into_iter()
                    .partition(|t| t.due <= now);
                *tasks = wait;
                due
            };
            for mut t in due {
                if !RUNTIME.current(generation) {
                    break;
                }
                if lock(&CANCELLED).contains(&t.id) {
                    continue;
                }
                let ran = match t.plugin {
                    Some(p) if failed(p) => continue,
                    Some(p) => guarded(p, "scheduled task", || (t.run)(game)).is_some(),
                    None => {
                        let Some(_callback) = RUNTIME.enter() else {
                            break;
                        };
                        catch_unwind(AssertUnwindSafe(|| (t.run)(game)))
                            .map_err(|e| note(
                                format!("A scheduled task panicked: {}", panic_text(&* e)),
                            ))
                            .is_ok()
                    }
                };
                let cancelled = {
                    let mut c = lock(&CANCELLED);
                    let had = c.contains(&t.id);
                    c.retain(|&i| i != t.id);
                    had
                };
                if let (true, false, Some(every)) = (
                    ran && RUNTIME.current(generation),
                    cancelled,
                    t.every,
                ) {
                    t.due = now + every;
                    let mut tasks = lock(&TASKS);
                    if RUNTIME.current(generation) {
                        tasks.push(t);
                    }
                }
            }
            lock(&CANCELLED).clear();
        }
