        fn no_module(name: &str) -> String {
            let n = super::sunset::norm(name);
            let near: Vec<&'static str> = with(|s| {
                s.modules
                    .iter()
                    .filter(|m| {
                        let mn = super::sunset::norm(m.name);
                        !n.is_empty()
                            && (mn.contains(&n) || n.contains(&mn)
                                || mn.starts_with(&n[..n.len().min(3)]))
                    })
                    .map(|m| m.name)
                    .take(5)
                    .collect()
            });
            if near.is_empty() {
                format!("No module called \"{name}\". .modules lists them all.")
            } else {
                format!("No module called \"{name}\". Did you mean {}?", near.join(", "))
            }
        }
        #[allow(dead_code)]
        pub(super) fn toggle(
            game: &mut Game<'_>,
            name: &str,
            on: bool,
        ) -> Result<(), String> {
            if !RUNTIME.running() {
                return Err("Sunset is stopped until the game restarts.".into());
            }
            let Some((i, now)) = with(|s| s.find(name).map(|i| (i, s.modules[i].on)))
            else {
                return Err(no_module(name));
            };
            if super::sunset::gui_only(name) {
                return Err(format!("{name} only turns on in the ClickGUI."));
            }
            if now != on {
                super::sunset::toggle(game, i, false);
            }
            Ok(())
        }
