        #[allow(dead_code)]
        pub(super) fn set(
            game: &Game<'_>,
            module: &str,
            setting: &str,
            value: impl SettingValue,
        ) -> Result<String, String> {
            use super::sunset::Value;
            if !RUNTIME.running() {
                return Err("Sunset is stopped until the game restarts.".into());
            }
            let value = value.text();
            let Some(i) = with(|s| s.find(module)) else {
                return Err(no_module(module));
            };
            let result = with(|s| {
                let m = &mut s.modules[i];
                let want = super::sunset::norm(setting);
                let Some(st) = m
                    .settings
                    .iter_mut()
                    .find(|st| super::sunset::norm(st.name) == want) else {
                    let names: Vec<&str> = m.settings.iter().map(|st| st.name).collect();
                    return Err(
                        format!(
                            "{} has no setting \"{setting}\". Its settings: {}.", m.name,
                            names.join(", ")
                        ),
                    );
                };
                let hint = match &st.value {
                    Value::Bool(_) => "true or false".to_owned(),
                    Value::Num { min, max, .. } => {
                        format!(
                            "a number from {} to {}", super::sunset::num(* min),
                            super::sunset::num(* max)
                        )
                    }
                    Value::Pick { of, .. } => format!("one of: {}", of.join(", ")),
                    Value::Text(_) => "text".to_owned(),
                };
                if !st.parse(&value) {
                    return Err(
                        format!(
                            "\"{value}\" is not a value for {} > {}: give {hint}.", m
                            .name, st.name
                        ),
                    );
                }
                Ok(st.shown())
            });
            if result.is_ok() {
                super::sunset::save(game);
            }
            result
        }
