        pub(super) fn send(
            game: &mut Game<'_>,
            packet: Serverbound,
        ) -> Result<(), String> {
            if !RUNTIME.running() {
                return Err("Sunset is stopped.".into());
            }
            if is_move(&packet) {
                return Err(
                    "Move packets can't be sent by a plugin (one a tick; a second gets you kicked): use turn/turn_then for the look, or change the tick's own one in on_packet_out."
                        .to_owned(),
                );
            }
            if matches!(packet, Serverbound::SetCarriedItem(_)) {
                return Err(
                    "Change the held slot with api::hold(game, slot): a second slot change flags anticheats."
                        .to_owned(),
                );
            }
            if game.remote.is_none() {
                return Err(
                    "Not connected: send packets in a world only (check api::in_world)."
                        .to_owned(),
                );
            }
            game.send(packet);
            Ok(())
        }
