    pub(crate) mod sunset_atmosphere {
        use crate::game::sunset_compat::SunsetGame as _;
        use super::{Dim, Game};
        use super::sunset::{Category, ID, Module};
        use ::sunset_core::atmosphere::{Config, configure};
        use ::sunset_core::fog::CUSTOM as FOG;
        pub(super) fn defaults() -> Vec<Module> {
            vec![
                Module::new("Atmosphere", Category::Render, "Custom skies.").pick("Mode",
                & ["Space", "Aurora", "Ringed Planet", "None"]).pick("Quality", &
                ["Balanced", "Performance", "Detailed"]).num("Brightness", 1.0, 0.2, 2.0,
                0.1).num("Effect strength", 1.0, 0.0, 2.0, 0.1).num("Stars", 1.0, 0.0,
                2.0, 0.1).num("Speed", 1.0, 0.0, 2.0, 0.1).num("Daytime strength", 0.65,
                0.0, 1.0, 0.05).bool("Custom fog", false).num("Fog start", 90.0, 0.0,
                200.0, 5.0).num("Fog end", 150.0, 0.0, 200.0, 5.0).colour("Fog color",
                "White").bool("Cover horizon band", true)
            ]
        }
        pub(super) fn custom_fog() -> bool {
            FOG.lock().unwrap_or_else(|e| e.into_inner()).is_some()
        }
        pub(super) fn visible(m: &Module, name: &str) -> bool {
            match name {
                "Fog start" | "Fog end" | "Fog color" | "Cover horizon band" => {
                    m.b("Custom fog")
                }
                "Quality" | "Brightness" | "Effect strength" | "Stars" | "Speed"
                | "Daytime strength" => m.p("Mode") != "None",
                _ => true,
            }
        }
        pub(super) fn sync(game: &Game<'_>) {
            if !game.sunset_window() || !game.native_on(ID) {
                configure(Config::default());
                *FOG.lock().unwrap_or_else(|e| e.into_inner()) = None;
                return;
            }
            super::sunset::ensure_loaded(game);
            let world_supported = game.player.is_some() && game.remote.is_some()
                && game.title.is_none() && game.dim == Dim::Overworld;
            let config = super::sunset::with(|state| {
                let Some(m) = state.module("Atmosphere").filter(|m| m.on) else {
                    *FOG.lock().unwrap_or_else(|e| e.into_inner()) = None;
                    return Config::default();
                };
                *FOG.lock().unwrap_or_else(|e| e.into_inner()) = m
                    .b("Custom fog")
                    .then(|| {
                        let (lo, hi) = (
                            m.n("Fog start").min(m.n("Fog end")) as f32,
                            m.n("Fog start").max(m.n("Fog end")) as f32,
                        );
                        let c = m.c("Fog color");
                        let ch = |s: u32| ((c >> s) & 0xFF) as f32 / 255.0;
                        (lo, hi, [ch(16), ch(8), ch(0)], m.b("Cover horizon band"))
                    });
                Config {
                    enabled: m.p("Mode") != "None",
                    world_supported,
                    mode: match m.p("Mode") {
                        "Aurora" => 1,
                        "Ringed Planet" => 2,
                        _ => 0,
                    },
                    quality: match m.p("Quality") {
                        "Performance" => 0,
                        "Detailed" => 2,
                        _ => 1,
                    },
                    brightness: m.n("Brightness") as f32,
                    strength: m.n("Effect strength") as f32,
                    stars: m.n("Stars") as f32,
                    speed: m.n("Speed") as f32,
                    day_blend: m.n("Daytime strength") as f32,
                }
            });
            configure(config);
        }
    }
    pub(crate) mod sunset_explosive_policy {
        pub(super) fn in_range(from: [f64; 3], to: [f64; 3], range: f64) -> bool {
            if !range.is_finite() || range < 0.0
                || !from.iter().chain(to.iter()).all(|x| x.is_finite())
            {
                return false;
            }
            let squared = (0..3).map(|i| (from[i] - to[i]).powi(2)).sum::<f64>();
            squared.is_finite() && squared <= range * range
        }
        pub(super) fn samples(min: [f64; 3], max: [f64; 3]) -> Option<Vec<[f64; 3]>> {
            if !(0..3)
                .all(|i| {
                    min[i].is_finite() && max[i].is_finite()
                        && min[i].abs() <= 30_000_000.0 && max[i].abs() <= 30_000_000.0
                        && max[i] >= min[i] && max[i] - min[i] <= 16.0
                })
            {
                return None;
            }
            let step: [f64; 3] = std::array::from_fn(|i| {
                1.0 / ((max[i] - min[i]) * 2.0 + 1.0)
            });
            let offset = [
                (1.0 - (1.0 / step[0]).floor() * step[0]) / 2.0,
                0.0,
                (1.0 - (1.0 / step[2]).floor() * step[2]) / 2.0,
            ];
            let mut result = Vec::with_capacity(64);
            let mut x = 0.0;
            while x <= 1.0 {
                let mut y = 0.0;
                while y <= 1.0 {
                    let mut z = 0.0;
                    while z <= 1.0 {
                        if result.len() >= 256 {
                            return None;
                        }
                        result
                            .push([
                                min[0] + (max[0] - min[0]) * x + offset[0],
                                min[1] + (max[1] - min[1]) * y,
                                min[2] + (max[2] - min[2]) * z + offset[2],
                            ]);
                        z += step[2];
                    }
                    y += step[1];
                }
                x += step[0];
            }
            Some(result)
        }
        pub(super) fn raw_damage(
            distance: f64,
            power: f32,
            exposure: f32,
        ) -> Option<f32> {
            if !distance.is_finite() || distance < 0.0 || !power.is_finite()
                || power <= 0.0 || power > 8.0 || !exposure.is_finite()
                || !(0.0..=1.0).contains(&exposure)
            {
                return None;
            }
            let diameter = f64::from(power * 2.0);
            let normalized = distance / diameter;
            if normalized > 1.0 {
                return Some(0.0);
            }
            let impact = (1.0 - normalized) * f64::from(exposure);
            Some(((impact * impact + impact) / 2.0 * 7.0 * diameter + 1.0) as f32)
        }
        #[derive(Clone, Debug)]
        pub(super) struct Budget {
            limit: usize,
            pub predictions: usize,
            pub rays: usize,
            pub rejected: usize,
        }
        impl Budget {
            pub(super) fn new(max_predictions: usize) -> Self {
                Self {
                    limit: max_predictions.min(64),
                    predictions: 0,
                    rays: 0,
                    rejected: 0,
                }
            }
            pub(super) fn prediction(&mut self, rays: usize) -> bool {
                if self.predictions >= self.limit || rays > 256
                    || self.rays.saturating_add(rays) > 4096
                {
                    self.rejected = self.rejected.saturating_add(1);
                    return false;
                }
                self.predictions += 1;
                self.rays += rays;
                true
            }
            pub(super) fn line(&mut self) -> bool {
                if self.rays >= 4096 {
                    self.rejected = self.rejected.saturating_add(1);
                    return false;
                }
                self.rays += 1;
                true
            }
        }
    }
    pub(crate) mod sunset_loot_policy {
        pub const CAPACITY: usize = 16;
        pub const TTL_MS: u64 = 30_000;
        pub const DROP_MARGIN: f64 = 2.0;
        pub const EMPTY_GRACE_MS: u64 = 3_000;
        pub const LOOT_BOX: [f64; 3] = [8.0, 4.0, 8.0];
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        pub enum Reason {
            Clear,
            NearDeath,
            Overflow,
            InvalidBlast,
            ClockRewind,
            UnknownScene,
        }
        #[derive(Clone, Copy)]
        struct Spot {
            entity: i32,
            at: [f64; 3],
            since: u64,
            until: u64,
        }
        pub struct Guard {
            spots: [Option<Spot>; CAPACITY],
            overflow_until: u64,
            last_ms: u64,
        }
        impl Guard {
            pub const fn new() -> Self {
                Self {
                    spots: [None; CAPACITY],
                    overflow_until: 0,
                    last_ms: 0,
                }
            }
            pub fn clear(&mut self) {
                *self = Self::new();
            }
            fn expired(until: u64, now: u64) -> bool {
                until != u64::MAX && until <= now
            }
            fn prune(&mut self, now: u64) {
                for spot in &mut self.spots {
                    if spot.is_some_and(|s| Self::expired(s.until, now)) {
                        *spot = None;
                    }
                }
                if Self::expired(self.overflow_until, now) {
                    self.overflow_until = 0;
                }
            }
            pub fn unknown_death(&mut self, now: u64) {
                self.last_ms = self.last_ms.max(now);
                self.overflow_until = self
                    .overflow_until
                    .max(self.last_ms.saturating_add(TTL_MS));
            }
            pub fn record(&mut self, now: u64, entity: i32, at: [f64; 3]) {
                if now < self.last_ms || !valid(at) {
                    self.unknown_death(now);
                    return;
                }
                self.last_ms = now;
                self.prune(now);
                let until = now.saturating_add(TTL_MS);
                if let Some(old) = self
                    .spots
                    .iter_mut()
                    .flatten()
                    .find(|s| s.entity == entity && s.at == at)
                {
                    old.until = old.until.max(until);
                    return;
                }
                if let Some(cell) = self.spots.iter_mut().find(|s| s.is_none()) {
                    *cell = Some(Spot {
                        entity,
                        at,
                        since: now,
                        until,
                    });
                } else {
                    self.overflow_until = self.overflow_until.max(until);
                }
            }
            pub fn release_empty(&mut self, now: u64, loot: impl Fn([f64; 3]) -> bool) {
                for spot in &mut self.spots {
                    if spot
                        .is_some_and(|s| {
                            now.saturating_sub(s.since) > EMPTY_GRACE_MS && !loot(s.at)
                        })
                    {
                        *spot = None;
                    }
                }
            }
            pub fn check(&mut self, now: u64, center: [f64; 3], power: f32) -> Reason {
                if !valid(center) || !power.is_finite() || power <= 0.0 || power > 16.0 {
                    return Reason::InvalidBlast;
                }
                if now < self.last_ms {
                    return Reason::ClockRewind;
                }
                self.last_ms = now;
                self.prune(now);
                if self.overflow_until != 0 {
                    return Reason::Overflow;
                }
                let reach = f64::from(power) * 2.0 + DROP_MARGIN;
                if self
                    .spots
                    .iter()
                    .flatten()
                    .any(|spot| {
                        (0..3).map(|i| (center[i] - spot.at[i]).powi(2)).sum::<f64>()
                            <= reach * reach
                    })
                {
                    Reason::NearDeath
                } else {
                    Reason::Clear
                }
            }
        }
        fn valid(at: [f64; 3]) -> bool {
            at.iter().all(|v| v.is_finite() && v.abs() <= 30_000_000.0)
        }
        #[derive(Clone, Copy, PartialEq, Eq)]
        pub struct Dimension {
            bytes: [u8; 256],
            len: usize,
        }
        impl Dimension {
            pub fn of(name: &str) -> Option<Self> {
                if name.is_empty() || name.len() > 256 {
                    return None;
                }
                let mut bytes = [0; 256];
                bytes[..name.len()].copy_from_slice(name.as_bytes());
                Some(Self { bytes, len: name.len() })
            }
        }
    }
    pub(crate) mod sunset_loot_guard {
        use crate::game::sunset_compat::SunsetGame as _;
        use super::remote::sunset_loot_remote::{self, Death};
        use super::sunset_explosive_damage::Blast;
        use super::sunset_loot_policy::{Dimension, Guard, LOOT_BOX, Reason};
        use super::{Game, sunset};
        use horizon_protocol::{connection::Counters, packets::play::Clientbound as C};
        use std::{
            sync::{Arc, Mutex, OnceLock},
            time::Instant,
        };
        type Session = Arc<Mutex<Option<Arc<Counters>>>>;
        struct State {
            session: Option<Session>,
            dimension: Option<Dimension>,
            guard: Guard,
            last: Reason,
            blocked: u64,
        }
        static STATE: Mutex<State> = Mutex::new(State {
            session: None,
            dimension: None,
            guard: Guard::new(),
            last: Reason::Clear,
            blocked: 0,
        });
        static START: OnceLock<Instant> = OnceLock::new();
        fn now() -> u64 {
            START
                .get_or_init(Instant::now)
                .elapsed()
                .as_millis()
                .min(u128::from(u64::MAX)) as u64
        }
        fn state<R>(f: impl FnOnce(&mut State) -> R) -> R {
            f(&mut STATE.lock().unwrap_or_else(|e| e.into_inner()))
        }
        fn same_session(game: &Game<'_>, s: &State) -> bool {
            game.remote
                .as_ref()
                .zip(s.session.as_ref())
                .is_some_and(|(r, old)| Arc::ptr_eq(&r.session.counters, old))
        }
        fn scene(game: &Game<'_>, name: &str, login: bool) {
            let dimension = Dimension::of(name);
            state(|s| {
                if login || !same_session(game, s) || s.dimension != dimension {
                    s.guard.clear();
                    s.last = Reason::Clear;
                }
                s.session = game.remote.as_ref().map(|r| r.session.counters.clone());
                s.dimension = dimension;
            });
        }
        pub(super) fn packet(game: &Game<'_>, packet: &C) {
            if !game.sunset_window() {
                return;
            }
            match packet {
                C::Login(p) => scene(game, &p.spawn.dimension, true),
                C::Respawn(p) => scene(game, &p.spawn.dimension, false),
                C::Disconnect(_) => {
                    state(|s| {
                        s.session = None;
                        s.dimension = None;
                        s.guard.clear();
                        s.last = Reason::Clear;
                    })
                }
                C::EntityEvent(p) if p.event == 3 && game.native_on(sunset::ID) => {
                    let death = sunset_loot_remote::player_death(game, p.id);
                    if matches!(death, Death::Other) {
                        return;
                    }
                    state(|s| {
                        if !same_session(game, s) || s.dimension.is_none() {
                            return;
                        }
                        match death {
                            Death::Player(Some(at)) => s.guard.record(now(), p.id, at),
                            Death::Player(None) => s.guard.unknown_death(now()),
                            Death::Other => {}
                        }
                    });
                }
                _ => {}
            }
        }
        pub(super) fn allows(game: &Game<'_>, blast: Blast, protect: bool) -> bool {
            if !protect {
                return true;
            }
            let feet = game
                .player
                .as_ref()
                .map(|p| [p.position.x, p.position.y, p.position.z]);
            let loot = |at: [f64; 3]| {
                feet
                    .is_none_or(|f| {
                        (0..3).map(|i| (f[i] - at[i]).powi(2)).sum::<f64>() > 32.0 * 32.0
                    })
                    || game
                        .dropped
                        .iter()
                        .any(|item| {
                            let p = [item.position.x, item.position.y, item.position.z];
                            (0..3).all(|i| (p[i] - at[i]).abs() <= LOOT_BOX[i])
                        })
            };
            state(|s| {
                s.guard.release_empty(now(), loot);
                s.last = if !same_session(game, s) || s.dimension.is_none() {
                    Reason::UnknownScene
                } else {
                    s.guard.check(now(), blast.center, blast.power)
                };
                let allowed = s.last == Reason::Clear;
                if !allowed {
                    s.blocked = s.blocked.saturating_add(1);
                }
                allowed
            })
        }
    }
