        pub(super) fn visible(m: &Module, name: &str) -> bool {
            let (aura, macro_on, advanced) = (
                m.b("Aura"),
                m.b("Macro"),
                m.b("Advanced"),
            );
            let tuned = aura && advanced;
            let render = aura && m.b("Render");
            match name {
                "Aura" | "Macro" => true,
                "Max self damage" | "Switch back" => aura || macro_on,
                "Obsidian delay" => macro_on && m.b("Auto obsidian"),
                "Perfect timing" | "Place delay" | "Break delay" | "Auto obsidian"
                | "Human pace" | "Protect loot" => macro_on,
                "Advanced" | "Target range" | "Min damage" | "Anti suicide"
                | "Break mode" | "Silent rotation" | "Render" => aura,
                "Silent FOV" => tuned && m.b("Silent rotation"),
                "Momentum weight" => tuned && m.p("Momentum") != "None",
                "Turn cost cap" => tuned && m.n("Turn cost") > 0.0,
                "Lead ticks" | "Ping lead" | "Max lead" => tuned && m.b("Predict target"),
                "Self lead ticks" | "Self max lead" => tuned && m.b("Predict self"),
                "Render target" | "Render placement" | "Render candidates" => {
                    tuned && render
                }
                "Target color" => tuned && render && m.b("Render target"),
                "Obsidian color" | "Crystal color" => {
                    tuned && render && m.b("Render placement")
                }
                "Candidates shown" | "Candidate color" => {
                    tuned && render && m.b("Render candidates")
                }
                _ => tuned,
            }
        }
