                    *s = State {
                        generation,
                        scene: game
                            .remote
                            .as_ref()
                            .map(|r| Scene {
                                session: r.session.counters.clone(),
                                dim: game.dim,
                                id: r.entity_id,
                            }),
                        ..State::default()
                    };
