        /// `FeatureToggle`.
        #[derive(Debug)]
        pub struct FeatureToggle {
            enabled: AtomicBool,
        }
        impl FeatureToggle {
            pub fn new(flag: bool) -> FeatureToggle {
                FeatureToggle {
                    enabled: AtomicBool::new(flag),
                }
            }
            pub fn set(&self, flag: bool) {
                self.enabled.store(flag, Ordering::Relaxed);
            }
            pub fn get(&self) -> bool {
                self.enabled.load(Ordering::Relaxed)
            }
        }
        /// `Config.RenderType`.
        #[derive(Clone, Copy, PartialEq, Eq, Debug)]
        pub enum RenderType {
            Off,
            On,
            Xray,
        }
        impl RenderType {
            pub const ALL: [RenderType; 3] = [
                RenderType::Off,
                RenderType::On,
                RenderType::Xray,
            ];
            /// The name of the Java constant (`toString`).
            pub fn name(self) -> &'static str {
                match self {
                    RenderType::Off => "OFF",
                    RenderType::On => "ON",
                    RenderType::Xray => "XRAY",
                }
            }
            pub fn from_name(name: &str) -> Option<RenderType> {
                Self::ALL.into_iter().find(|r| r.name() == name)
            }
        }
        /// The toggles of the finders, in the order the Java declares them.
