        fn poke(phase: Phase) -> DataAddedEvent {
            Arc::new(move |s: &DataStorage| s.get_time_machine().poke(s, Some(phase)))
        }
        /// `world.getNoiseBiome((chunkX << 2) + 2, y, (chunkZ << 2) + 2)`, as the library's biome.
        fn noise_biome_at(level: &dyn Level, chunk_pos: ChunkPos, y: i32) -> i32 {
            biome_fixer_swap(
                level.noise_biome((chunk_pos.x << 2) + 2, y, (chunk_pos.z << 2) + 2),
            )
        }
        /// `BlockFinder.findInChunk`: the world positions in the chunk, from the local search positions, holding one of the blocks.
        fn block_find(
            level: &dyn Level,
            chunk_pos: ChunkPos,
            positions: &[BlockPos],
            targets: &[&str],
        ) -> Vec<BlockPos> {
            let origin = chunk_pos.get_world_position();
            let mut result = Vec::new();
            if !level.is_chunk_loaded(chunk_pos.x, chunk_pos.z) {
                return result;
            }
            for p in positions {
                if level.cancelled() {
                    return Vec::new();
                }
                let w = origin.offset_pos(*p);
                if targets.contains(&level.block(w.x, w.y, w.z)) {
                    result.push(w);
                }
            }
            result
        }
        macro_rules! finder_base {
            () => {
                fn base(& self) -> & FinderBase { & self.base } fn base_mut(& mut self)
                -> & mut FinderBase { & mut self.base }
            };
        }
        fn structure_feature(f: &Option<Arc<Feature>>) -> Option<&Arc<Feature>> {
            f.as_ref()
        }
        fn is_valid_structure_biome(feature: &Arc<Feature>, biome: i32) -> bool {
            match &**feature {
                Feature::Structure(s) => s.is_valid_biome(biome),
                Feature::Decorator(d) => d.is_valid_biome(biome),
            }
        }
        const CHEST_HOLDERS: [&str; 9] = [
            "sandstone",
            "stone",
            "andesite",
            "granite",
            "diorite",
            "coal_ore",
            "iron_ore",
            "gold_ore",
            "gravel",
        ];
        pub struct BuriedTreasureFinder {
            base: FinderBase,
        }
        impl BuriedTreasureFinder {
            pub fn create(
                _ctx: &FinderContext,
                level: &dyn Level,
                chunk_pos: ChunkPos,
            ) -> Vec<Box<dyn Finder>> {
                vec![
                    Box::new(BuriedTreasureFinder { base : FinderBase::new(chunk_pos,
                    level.dimension()) })
                ]
            }
        }
        impl Finder for BuriedTreasureFinder {
            finder_base!();
            fn find_in_chunk(
                &mut self,
                ctx: &FinderContext,
                level: &dyn Level,
            ) -> Vec<BlockPos> {
                if ctx.storage.cancelled() || level.cancelled()
                    || !level
                        .is_chunk_loaded(self.base.chunk_pos.x, self.base.chunk_pos.z)
                {
                    return Vec::new();
                }
                let Some(feature) = structure_feature(&ctx.features.buried_treasure)
                else { return Vec::new() };
                let chunk_pos = self.base.chunk_pos;
                let biome = noise_biome_at(level, chunk_pos, 64);
                if !is_valid_structure_biome(feature, biome) {
                    return Vec::new();
                }
                let mut result = block_find(
                    level,
                    chunk_pos,
                    &ctx.search.buried_treasure,
                    &["chest"],
                );
                result
                    .retain(|pos| {
                        if level.property(pos.x, pos.y, pos.z, "waterlogged")
                            == Some("true")
                        {
                            return false;
                        }
                        CHEST_HOLDERS.contains(&level.block(pos.x, pos.y - 1, pos.z))
                    });
                for pos in &result {
                    if ctx.storage.cancelled() || level.cancelled() {
                        return Vec::new();
                    }
                    let data = FeatureData::structure(feature, chunk_pos.x, chunk_pos.z);
                    if ctx.storage.add_base_data(data, poke(Phase::Structures)) {
                        self.base
                            .cuboids
                            .push(Cuboid::block(*pos, argb_color(255, 255, 0)));
                    }
                }
                result
            }
            fn is_valid_dimension(&self, dimension: Dimension) -> bool {
                dimension == Dimension::Overworld
            }
        }
