        fn find_gateway_height(level: &dyn Level, pos: BlockPos) -> i32 {
            let mut pos = pos;
            let mut height = 0;
            while pos.y >= 0 {
                if level.cancelled() {
                    return -1;
                }
                pos = pos.below();
                height += 1;
                let block = level.block(pos.x, pos.y, pos.z);
                if block == "bedrock" || block != "end_stone" {
                    continue;
                }
                break;
            }
            height - 1
        }
        impl Finder for EndGatewayFinder {
            finder_base!();
            fn find_in_chunk(
                &mut self,
                ctx: &FinderContext,
                level: &dyn Level,
            ) -> Vec<BlockPos> {
                if ctx.storage.cancelled() || level.cancelled()
                    || !level
                        .is_chunk_loaded(self.base.chunk_pos.x, self.base.chunk_pos.z)
                {
                    return Vec::new();
                }
                let Some(feature) = structure_feature(&ctx.features.end_gateway) else {
                    return Vec::new()
                };
                let chunk_pos = self.base.chunk_pos;
                let biome = noise_biome_at(level, chunk_pos, 64);
                if !is_valid_structure_biome(feature, biome) {
                    return Vec::new();
                }
                let result = block_find(
                    level,
                    chunk_pos,
                    &ctx.search.chunk_positions,
                    &["end_gateway"],
                );
                let mut new_result = Vec::new();
                for pos in result {
                    if ctx.storage.cancelled() || level.cancelled() {
                        return Vec::new();
                    }
                    let height = find_gateway_height(level, pos);
                    if (3..=9).contains(&height) {
                        new_result.push(pos);
                        let data = FeatureData::end_gateway(
                            feature,
                            pos.x,
                            pos.z,
                            height,
                        );
                        if ctx.storage.add_base_data(data, poke(Phase::Structures)) {
                            self.base
                                .cuboids
                                .push(
                                    Cuboid::sized(
                                        pos.offset(-1, -2, -1),
                                        [3, 5, 3],
                                        argb_color(102, 102, 210),
                                    ),
                                );
                        }
                    }
                }
                new_result
            }
            fn is_valid_dimension(&self, dimension: Dimension) -> bool {
                dimension == Dimension::End
            }
        }
        pub struct EndPillarsFinder {
            base: FinderBase,
            already_found: bool,
            /// The chunk and the position of each pillar's bedrock marker.
            markers: Vec<ChunkPos>,
        }
        impl EndPillarsFinder {
            pub fn create(
                ctx: &FinderContext,
                level: &dyn Level,
                chunk_pos: ChunkPos,
            ) -> Vec<Box<dyn Finder>> {
                let already_found = ctx
                    .storage
                    .pillar_data
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .is_some();
                let mut markers = Vec::new();
                if !already_found {
                    let old = ctx.host().version().is_older_than(MCVersion::v1_14);
                    for i in 0..10 {
                        let angle = 2.0
                            * (-std::f64::consts::PI
                                + (std::f64::consts::PI / 10.0) * i as f64);
                        let (mut x, mut z) = (42.0 * angle.cos(), 42.0 * angle.sin());
                        if old {
                            x = (x + 0.5).floor();
                            z = (z + 0.5).floor();
                        }
                        markers
                            .push(
                                ChunkPos::new(
                                    (x.floor() as i32) >> 4,
                                    (z.floor() as i32) >> 4,
                                ),
                            );
                    }
                }
                vec![
                    Box::new(EndPillarsFinder { base : FinderBase::new(chunk_pos, level
                    .dimension()), already_found, markers })
                ]
            }
        }
        impl Finder for EndPillarsFinder {
            finder_base!();
            fn find_in_chunk(
                &mut self,
                ctx: &FinderContext,
                level: &dyn Level,
            ) -> Vec<BlockPos> {
                if ctx.storage.cancelled() || level.cancelled()
                    || !level
                        .is_chunk_loaded(self.base.chunk_pos.x, self.base.chunk_pos.z)
                {
                    return Vec::new();
                }
                let mut result = Vec::new();
                if self.markers.iter().any(|m| !level.is_chunk_loaded(m.x, m.z)) {
                    return Vec::new();
                }
                for marker in &self.markers {
                    result
                        .extend(
                            block_find(
                                level,
                                *marker,
                                &ctx.search.bedrock_marker,
                                &["bedrock"],
                            ),
                        );
                }
                if !self.already_found && result.len() == self.markers.len() {
                    let data = PillarData::new(result.iter().map(|p| p.y).collect());
                    if ctx.storage.add_pillar_data(data, poke(Phase::Pillars)) {
                        for pos in &result {
                            if ctx.storage.cancelled() || level.cancelled() {
                                return Vec::new();
                            }
                            self.base
                                .cuboids
                                .push(Cuboid::block(*pos, argb_color(128, 0, 128)));
                        }
                    }
                }
                result
            }
            fn is_valid_dimension(&self, dimension: Dimension) -> bool {
                dimension == Dimension::End
            }
        }
