        impl Finder for BiomeFinder {
            finder_base!();
            fn find_in_chunk(
                &mut self,
                ctx: &FinderContext,
                level: &dyn Level,
            ) -> Vec<BlockPos> {
                if ctx.storage.cancelled() || level.cancelled()
                    || !level
                        .is_chunk_loaded(self.base.chunk_pos.x, self.base.chunk_pos.z)
                {
                    return Vec::new();
                }
                let mut result = Vec::new();
                let version = ctx.host().version();
                let origin = self.base.chunk_pos.get_world_position();
                let mut x = 0;
                while x < 16 {
                    let mut z = 0;
                    while z < 16 {
                        if ctx.storage.cancelled() || level.cancelled() {
                            return Vec::new();
                        }
                        let block_pos = origin.offset(x, 0, z);
                        let path = if version.is_newer_or_equal_to(MCVersion::v1_15) {
                            level.noise_biome(block_pos.x >> 2, 0, block_pos.z >> 2)
                        } else {
                            level.biome(block_pos.x, block_pos.y, block_pos.z)
                        };
                        let other = biome_fixer_swap(path);
                        if other != biomes::THE_VOID {
                            let data = if version.is_newer_or_equal_to(MCVersion::v1_15)
                            {
                                BiomeData::new(other, block_pos.x >> 2, block_pos.z >> 2)
                            } else {
                                BiomeData::new(other, block_pos.x, block_pos.z)
                            };
                            if ctx.storage.add_biome_data(data, poke(Phase::Biomes)) {
                                let surface = BlockPos::new(
                                    block_pos.x,
                                    level.world_surface_height(block_pos.x, block_pos.z) - 1,
                                    block_pos.z,
                                );
                                if ctx.host().debug_enabled() {
                                    let name = super::sunset_scx_biome::get(other)
                                        .map_or("", |b| b.name);
                                    ctx.host()
                                        .warn(
                                            &format!(
                                                "{}, {}, {}, {name}", surface.x, surface.y, surface.z
                                            ),
                                            &[],
                                        );
                                }
                                result.push(surface);
                            }
                        }
                        z += 4;
                    }
                    x += 4;
                }
                for pos in &result {
                    if ctx.storage.cancelled() || level.cancelled() {
                        return Vec::new();
                    }
                    self.base
                        .cuboids
                        .push(Cuboid::block(*pos, argb_color(51, 204, 128)));
                }
                result
            }
            fn is_valid_dimension(&self, dimension: Dimension) -> bool {
                dimension == Dimension::Overworld
            }
        }
        type Builder = fn(&mut PieceFinder);
        fn pieces(
            kind: PieceKind,
            size: [i32; 3],
            positions: impl Fn(Direction) -> Arc<Vec<BlockPos>>,
            build: Builder,
        ) -> Vec<PieceFinder> {
            Direction::HORIZONTAL
                .iter()
                .map(|d| {
                    let mut p = PieceFinder::new(kind, Some(*d), size);
                    p.search_positions = positions(*d);
                    build(&mut p);
                    p
                })
                .collect()
        }
        #[derive(Clone, Copy, PartialEq, Eq)]
        enum TempleKind {
            DesertPyramid,
            JunglePyramid,
            SwampHut,
        }
        pub struct TempleFinder {
            base: FinderBase,
            kind: TempleKind,
            pieces: Vec<PieceFinder>,
        }
        impl TempleFinder {
            fn new(
                ctx: &FinderContext,
                level: &dyn Level,
                chunk_pos: ChunkPos,
                kind: TempleKind,
            ) -> TempleFinder {
                let (size, build): ([i32; 3], Builder) = match kind {
                    TempleKind::DesertPyramid => ([21, 15, 21], dsl::desert_pyramid),
                    TempleKind::JunglePyramid => ([12, 10, 15], dsl::jungle_pyramid),
                    TempleKind::SwampHut => ([7, 7, 9], dsl::swamp_hut),
                };
                let temple = ctx.search.temple.clone();
                TempleFinder {
                    base: FinderBase::new(chunk_pos, level.dimension()),
                    kind,
                    pieces: pieces(PieceKind::Piece, size, |_| temple.clone(), build),
                }
            }
            pub fn create_desert_pyramid(
                ctx: &FinderContext,
                level: &dyn Level,
                c: ChunkPos,
            ) -> Vec<Box<dyn Finder>> {
                [(0, 0), (-1, 0), (0, -1), (-1, -1)]
                    .iter()
                    .map(|(dx, dz)| {
                        Box::new(
                            TempleFinder::new(
                                ctx,
                                level,
                                ChunkPos::new(c.x + dx, c.z + dz),
                                TempleKind::DesertPyramid,
                            ),
                        ) as Box<dyn Finder>
                    })
                    .collect()
            }
            pub fn create_jungle_pyramid(
                ctx: &FinderContext,
                level: &dyn Level,
                c: ChunkPos,
            ) -> Vec<Box<dyn Finder>> {
                vec![
                    Box::new(TempleFinder::new(ctx, level, c, TempleKind::JunglePyramid))
                ]
            }
            pub fn create_swamp_hut(
                ctx: &FinderContext,
                level: &dyn Level,
                c: ChunkPos,
            ) -> Vec<Box<dyn Finder>> {
                vec![Box::new(TempleFinder::new(ctx, level, c, TempleKind::SwampHut))]
            }
        }
        impl Finder for TempleFinder {
            finder_base!();
            fn find_in_chunk(
                &mut self,
                ctx: &FinderContext,
                level: &dyn Level,
            ) -> Vec<BlockPos> {
                if ctx.storage.cancelled() || level.cancelled()
                    || !level
                        .is_chunk_loaded(self.base.chunk_pos.x, self.base.chunk_pos.z)
                {
                    return Vec::new();
                }
                let feature = match self.kind {
                    TempleKind::DesertPyramid => &ctx.features.desert_pyramid,
                    TempleKind::JunglePyramid => &ctx.features.jungle_pyramid,
                    TempleKind::SwampHut => &ctx.features.swamp_hut,
                };
                let Some(feature) = structure_feature(feature) else {
                    return Vec::new()
                };
                let chunk_pos = self.base.chunk_pos;
                let mut combined = Vec::new();
                for piece in &self.pieces {
                    if ctx.storage.cancelled() || level.cancelled() {
                        return Vec::new();
                    }
                    let biome = noise_biome_at(level, chunk_pos, 64);
                    let positions = if is_valid_structure_biome(feature, biome) {
                        piece.find_in_chunk(level, chunk_pos)
                    } else {
                        Vec::new()
                    };
                    for pos in &positions {
                        let data = FeatureData::structure(
                            feature,
                            chunk_pos.x,
                            chunk_pos.z,
                        );
                        if ctx.storage.add_base_data(data, poke(Phase::Lifting)) {
                            self.base
                                .cuboids
                                .push(
                                    Cuboid::sized(
                                        *pos,
                                        piece.get_layout(),
                                        argb_color(255, 0, 255),
                                    ),
                                );
                            let chunk_start = BlockPos::new(
                                pos.x & -16,
                                pos.y,
                                pos.z & -16,
                            );
                            self.base
                                .cuboids
                                .push(Cuboid::block(chunk_start, argb_color(255, 0, 255)));
                        }
                    }
                    combined.extend(positions);
                }
                combined
            }
            fn is_valid_dimension(&self, dimension: Dimension) -> bool {
                dimension == Dimension::Overworld
            }
        }
