        #[derive(Clone, Copy, Debug)]
        struct Scan {
            at: At,
            revision: u64,
        }
        struct Seen {
            chunk: Weak<Chunk>,
            arrived: u64,
            dirty: u64,
            sent: u64,
        }
        #[derive(Default)]
        struct Scans {
            seen: HashMap<At, Seen>,
            membership: u64,
            refreshed: u64,
            revision: u64,
            center: At,
        }
        impl Scans {
            fn refresh(
                &mut self,
                game: &Game<'_>,
                latest: &RwLock<Option<Arc<ChunkSnapshot>>>,
                dimension: Dimension,
            ) {
                let membership = game.world.chunks.membership_revision();
                let Some(player) = game.player.as_ref() else {
                    return;
                };
                let center = (
                    (player.position.x.floor() as i32) >> 4,
                    (player.position.z.floor() as i32) >> 4,
                );
                if membership == self.membership && center == self.center
                    && game.ticks.saturating_sub(self.refreshed) < 20
                {
                    return;
                }
                self.membership = membership;
                self.refreshed = game.ticks;
                self.center = center;
                let mut nearby: Vec<At> = game.world.chunks.keys().copied().collect();
                nearby
                    .sort_unstable_by_key(|&(x, z)| (
                        (i64::from(x) - i64::from(center.0))
                            .abs()
                            .max((i64::from(z) - i64::from(center.1)).abs()),
                        x,
                        z,
                    ));
                nearby.truncate(MAX_CHUNKS);
                let chunks: HashMap<At, Arc<Chunk>> = nearby
                    .into_iter()
                    .filter_map(|at| game.world.chunks.get(&at).map(|c| (at, c.clone())))
                    .collect();
                self.publish(chunks, game.ticks, latest, dimension);
            }
            fn publish(
                &mut self,
                chunks: HashMap<At, Arc<Chunk>>,
                tick: u64,
                latest: &RwLock<Option<Arc<ChunkSnapshot>>>,
                dimension: Dimension,
            ) {
                self.revision = self.revision.wrapping_add(1).max(1);
                let revision = self.revision;
                let mut changed: Vec<At> = self
                    .seen
                    .keys()
                    .filter(|k| !chunks.contains_key(k))
                    .copied()
                    .collect();
                self.seen.retain(|at, _| chunks.contains_key(at));
                for (&at, chunk) in &chunks {
                    match self.seen.get_mut(&at) {
                        Some(seen) => {
                            if !std::ptr::eq(seen.chunk.as_ptr(), Arc::as_ptr(chunk)) {
                                if tick.saturating_sub(seen.arrived) <= 600 {
                                    changed.push(at);
                                }
                                seen.chunk = Arc::downgrade(chunk);
                            }
                        }
                        None => {
                            self.seen
                                .insert(
                                    at,
                                    Seen {
                                        chunk: Arc::downgrade(chunk),
                                        arrived: tick,
                                        dirty: revision,
                                        sent: 0,
                                    },
                                );
                            changed.push(at);
                        }
                    }
                }
                for &other in &changed {
                    for dx in -4..=4 {
                        for dz in -4..=4 {
                            let (Some(x), Some(z)) = (
                                other.0.checked_add(dx),
                                other.1.checked_add(dz),
                            ) else {
                                continue;
                            };
                            if let Some(seen) = self.seen.get_mut(&(x, z)) {
                                seen.dirty = revision;
                            }
                        }
                    }
                }
                if dimension == Dimension::End
                    && changed.iter().any(|&at| in_pillar_ring(at))
                {
                    for (&at, seen) in &mut self.seen {
                        if in_pillar_ring(at) {
                            seen.dirty = revision;
                        }
                    }
                }
                *latest.write().unwrap_or_else(|e| e.into_inner()) = Some(
                    Arc::new(ChunkSnapshot { revision, chunks }),
                );
            }
            fn send(&mut self, sender: &SyncSender<Scan>) {
                let mut pending: Vec<At> = self
                    .seen
                    .iter()
                    .filter(|(_, s)| s.sent != s.dirty)
                    .map(|(&at, _)| at)
                    .collect();
                pending
                    .sort_unstable_by_key(|&(x, z)| (
                        (i64::from(x) - i64::from(self.center.0))
                            .abs()
                            .max((i64::from(z) - i64::from(self.center.1)).abs()),
                        x,
                        z,
                    ));
                for at in pending.into_iter().take(SEND_PER_TICK) {
                    let seen = self.seen.get_mut(&at).unwrap();
                    match sender.try_send(Scan { at, revision: seen.dirty }) {
                        Ok(()) => seen.sent = seen.dirty,
                        Err(TrySendError::Full(_) | TrySendError::Disconnected(_)) => {
                            break;
                        }
                    }
                }
            }
        }
        fn in_pillar_ring((x, z): At) -> bool {
            (-4..=4).contains(&x) && (-4..=4).contains(&z)
        }
        enum LocalSeed {
            Direct(i64),
            Saved(PathBuf),
        }
        struct WorkerInput {
            registry: &'static BlockRegistry,
            biomes: Vec<String>,
            dimension: Dimension,
            height: (i32, i32),
            local: Option<LocalSeed>,
            policy: Policy,
        }
        impl WorkerInput {
            fn of(game: &Game<'_>, policy: Policy) -> Self {
                let biomes = game
                    .world_biomes
                    .as_deref()
                    .unwrap_or_else(|| game.res.biomes());
                let dimension = match game.dim {
                    super::Dim::Nether => Dimension::Nether,
                    super::Dim::End => Dimension::End,
                    _ => Dimension::Overworld,
                };
                let local = if *FORCE_CRACK {
                    None
                } else {
                    match &game.remote {
                        None => game.sunset_local_seed().map(LocalSeed::Direct),
                        Some(_) if game.integrated.is_some() => {
                            game.integrated
                                .as_ref()
                                .map(|i| i.save_folder.clone())
                                .and_then(|folder| {
                                    std::env::current_dir()
                                        .ok()
                                        .map(|p| LocalSeed::Saved(p.join("saves").join(folder)))
                                })
                        }
                        _ => None,
                    }
                };
                Self {
                    registry: game.pack.assets.registry,
                    biomes: biomes
                        .list
                        .iter()
                        .take(8192)
                        .map(|b| b.name.clone())
                        .collect(),
                    dimension,
                    height: (game.world.shape.min_y, game.world.shape.max_y()),
                    local,
                    policy,
                }
            }
        }
        struct Run {
            host: Arc<GameHost>,
            storage: Arc<DataStorage>,
            input: SyncSender<Scan>,
            latest: Arc<RwLock<Option<Arc<ChunkSnapshot>>>>,
            worker: JoinHandle<()>,
            scans: Scans,
            dimension: Dimension,
        }
        impl Run {
            fn start(
                game: &Game<'_>,
                world: u64,
                run: u64,
                hash: Option<i64>,
                policy: Policy,
                cache: Arc<Mutex<VerifiedSeeds>>,
            ) -> Result<Self, String> {
                let host = GameHost::new(world, run, hash, cache);
                let storage = DataStorage::new(host.clone());
                storage.get_time_machine().set_threads(policy.threads);
                let latest = Arc::new(RwLock::new(None));
                let (input, receiver) = sync_channel(QUEUE_SIZE);
                let init = WorkerInput::of(game, policy);
                let dimension = init.dimension;
                let (h, s, view) = (host.clone(), storage.clone(), latest.clone());
                let worker = std::thread::Builder::new()
                    .name("sunset-seedcracker".into())
                    .spawn(move || {
                        let mut solver = None;
                        let mut database = None;
                        let result = std::panic::catch_unwind(
                            std::panic::AssertUnwindSafe(|| coordinate(
                                &h,
                                &s,
                                &view,
                                receiver,
                                init,
                                &mut solver,
                                &mut database,
                            )),
                        );
                        s.get_time_machine().terminate();
                        if let Some(handle) = solver {
                            let _ = handle.join();
                        }
                        if let Some(handle) = database {
                            let _ = handle.join();
                        }
                        if result.is_err() {
                            h.failed("Seed search failed; use .seed restart to retry");
                        }
                        *view.write().unwrap_or_else(|e| e.into_inner()) = None;
                        h.finished.store(true, Ordering::Release);
                    })
                    .map_err(|e| bounded(&format!("Could not start seed search: {e}")))?;
                Ok(Self {
                    host,
                    storage,
                    input,
                    latest,
                    worker,
                    scans: Scans::default(),
                    dimension,
                })
            }
            fn retire(self) -> JoinHandle<()> {
                self.host.cancelled.store(true, Ordering::Release);
                self.storage.get_time_machine().terminate();
                *self.latest.write().unwrap_or_else(|e| e.into_inner()) = None;
                self.worker
            }
        }
        fn fetch_database(
            host: &GameHost,
            policy: Policy,
            fetch: impl FnOnce() -> Result<String, String>,
        ) {
            if !policy.automatic || !policy.database || host.cancelled()
                || host.hash.is_none()
            {
                return;
            }
            if host.database_started.swap(true, Ordering::AcqRel) || host.cancelled() {
                return;
            }
            match fetch() {
                Ok(csv) if !host.cancelled() => {
                    let mut database = Database::default();
                    database.parse_csv(&csv);
                    if let Some(seed) = host
                        .hash
                        .and_then(|h| database.get_seed_by_hash(h))
                    {
                        if verified(seed, host.hash) {
                            host.found(seed, SeedOrigin::Database);
                        } else {
                            host.failed(
                                "Database row did not match this world's seed hash",
                            );
                        }
                    } else {
                        host.update(|s| {
                            if s.found.is_none() {
                                s.detail = Some(
                                    "No matching database seed; collecting structures".into(),
                                );
                            }
                        });
                    }
                }
                Err(why) => host.failed(&why),
                _ => {}
            }
        }
        fn database_get() -> Result<String, String> {
            let response = ureq::AgentBuilder::new()
                .timeout(Duration::from_secs(10))
                .redirects(5)
                .build()
                .get(DATABASE_URL)
                .set("User-Agent", "Sunset SeedCracker")
                .call()
                .map_err(|_| "Seed database could not be reached".to_owned())?;
            let mut body = Vec::new();
            response
                .into_reader()
                .take(MAX_DATABASE + 1)
                .read_to_end(&mut body)
                .map_err(|_| "Seed database response could not be read".to_owned())?;
            if body.len() as u64 > MAX_DATABASE {
                return Err("Seed database response exceeded 2 MiB".into());
            }
            String::from_utf8(body)
                .map_err(|_| "Seed database returned invalid text".into())
        }
        fn coordinate(
            host: &Arc<GameHost>,
            storage: &Arc<DataStorage>,
            latest: &RwLock<Option<Arc<ChunkSnapshot>>>,
            input: Receiver<Scan>,
            init: WorkerInput,
            solver: &mut Option<JoinHandle<()>>,
            database: &mut Option<JoinHandle<()>>,
        ) {
            if host.cancelled() {
                return;
            }
            let local = match init.local {
                Some(LocalSeed::Direct(value)) => Some(value),
                Some(LocalSeed::Saved(path)) => {
                    horizon_client::save::Level::read(&path).map(|l| l.seed)
                }
                None => None,
            };
            if let Some(value) = local {
                host.found(value, SeedOrigin::Local);
                if lock(&host.published).found.is_some() {
                    return;
                }
            }
            if host.cancelled() {
                return;
            }
            if init.policy.database && host.hash.is_some() {
                let h = host.clone();
                let policy = init.policy;
                match std::thread::Builder::new()
                    .name("sunset-seed-database".into())
                    .spawn(move || fetch_database(&h, policy, database_get))
                {
                    Ok(handle) => *database = Some(handle),
                    Err(_) => host.failed("Could not start seed database request"),
                }
            }
            let mut config = Config::default();
            config.active = true;
            config.render = RenderType::Off;
            config.anti_xray_bypass = false;
            config.database_submits = false;
            let features = Arc::new(Features::init(host.version(), &config, &|_| {}));
            let search = Arc::new(
                SearchPositions::reload_height(init.height.0, init.height.1),
            );
            let table = Arc::new(StateTable::build(init.registry, &init.biomes));
            let ctx = FinderContext {
                features,
                search,
                storage: storage.clone(),
                anti_xray_bypass: false,
            };
            if let Some(hash) = host.hash {
                let poke: DataAddedEvent = Arc::new(|s| {
                    s.get_time_machine().poke(s, Some(Phase::Biomes))
                });
                storage.add_hashed_seed_data(HashedSeedData::new(hash), poke);
            }
            let collecting_since = Instant::now();
            loop {
                if host.cancelled() || lock(&host.published).found.is_some() {
                    break;
                }
                if solver.as_ref().is_some_and(JoinHandle::is_finished) {
                    if solver.take().unwrap().join().is_err() {
                        host.failed("Seed solver failed; use .seed restart to retry");
                        return;
                    }
                }
                if solver.is_none() && collecting_since.elapsed() >= *START_DELAY {
                    *solver = storage.tick();
                }
                let job = match input.recv_timeout(Duration::from_millis(50)) {
                    Ok(job) => Some(job),
                    Err(RecvTimeoutError::Timeout) => None,
                    Err(RecvTimeoutError::Disconnected) => break,
                };
                if let Some(job) = job {
                    let chunks = latest
                        .read()
                        .unwrap_or_else(|e| e.into_inner())
                        .clone();
                    if let Some(chunks) = chunks {
                        if chunks.revision < job.revision
                            || !chunks.chunks.contains_key(&job.at)
                        {
                            continue;
                        }
                        let level = WorldView::new(
                            chunks,
                            table.clone(),
                            init.dimension,
                            host.cancelled.clone(),
                            host.lifecycle,
                        );
                        for (kind, builder) in &BUILDERS {
                            if host.cancelled() || !kind.enabled(&config).get() {
                                continue;
                            }
                            if storage.observation_count() >= MAX_OBSERVATIONS {
                                break;
                            }
                            for mut finder in builder(
                                &ctx,
                                &level,
                                ChunkPos::new(job.at.0, job.at.1),
                            ) {
                                if host.cancelled()
                                    || storage.observation_count() >= MAX_OBSERVATIONS
                                {
                                    break;
                                }
                                if finder.is_valid_dimension(init.dimension) {
                                    finder.find_in_chunk(&ctx, &level);
                                }
                            }
                        }
                    }
                }
                host.metrics(storage);
            }
        }
        #[derive(Default)]
        struct Controller {
            world: u64,
            run: u64,
            identity: Option<Identity>,
            policy: Option<Policy>,
            active: Option<Run>,
            retiring: Option<JoinHandle<()>>,
            idle: Snapshot,
            start_failed: bool,
            cache: Arc<Mutex<VerifiedSeeds>>,
        }
        impl Controller {
            fn retire(&mut self) {
                if let Some(run) = self.active.take() {
                    self.retiring = Some(run.retire());
                }
                self.idle = Snapshot {
                    world: self.world,
                    run: self.run,
                    ..Snapshot::default()
                };
                self.start_failed = false;
            }
            fn boundary(&mut self) {
                self.retire();
                self.world = self.world.wrapping_add(1).max(1);
                self.identity = None;
                self.policy = None;
                self.idle.world = self.world;
            }
            fn reap(&mut self) {
                if self.retiring.as_ref().is_some_and(JoinHandle::is_finished) {
                    let _ = self.retiring.take().unwrap().join();
                }
            }
            fn read(&self) -> Snapshot {
                if let Some(run) = &self.active {
                    if !run.host.cancelled() {
                        return lock(&run.host.published).clone();
                    }
                }
                self.idle.clone()
            }
            fn reuse(&mut self, hash: Option<i64>) {
                if self.active.is_some() || self.idle.found.is_some() {
                    return;
                }
                let Some(value) = lock(&self.cache).get(hash) else {
                    return;
                };
                self.run = self.run.wrapping_add(1).max(1);
                self.idle = Snapshot {
                    world: self.world,
                    run: self.run,
                    phase: "Seed reused".into(),
                    world_candidates: 1,
                    found: Some(FoundSeed {
                        world: self.world,
                        run: self.run,
                        value,
                        origin: SeedOrigin::Reused,
                    }),
                    ..Snapshot::default()
                };
            }
            fn synchronize(&mut self, game: &Game<'_>, policy: Policy) {
                self.reap();
                let next = Identity::of(game);
                let same = match (&self.identity, &next) {
                    (Some(old), Some(new)) => old.same(new, game),
                    (None, None) => true,
                    _ => false,
                };
                if !same {
                    self.boundary();
                    self.identity = next;
                }
                if self.policy != Some(policy) {
                    self.retire();
                    self.policy = Some(policy);
                }
                if !policy.automatic || self.identity.is_none() || !RUNTIME.running() {
                    if self.active.is_some() {
                        self.retire();
                    }
                    self.idle.phase = if policy.automatic {
                        "Waiting for world"
                    } else {
                        "Off"
                    }
                        .into();
                } else if !*FORCE_CRACK {
                    self.reuse(self.identity.as_ref().and_then(|i| i.hash));
                }
            }
        }
        static CONTROLLER: LazyLock<Mutex<Controller>> = LazyLock::new(|| Mutex::new(
            Controller::default(),
        ));
        fn current_policy() -> Policy {
            let modules = super::sunset::snapshot();
            Policy::of(modules.iter().find(|m| m.name == super::sunset_ore_sim::NAME))
        }
        pub(super) fn maintain(game: &Game<'_>) {
            if !game.sunset_window() {
                return;
            }
            let policy = current_policy();
            lock(&CONTROLLER).synchronize(game, policy);
        }
        pub(super) fn tick(game: &mut Game<'_>, module: Option<&Module>) {
            if !game.sunset_window() {
                return;
            }
            let policy = Policy::of(module);
            let mut c = lock(&CONTROLLER);
            c.synchronize(game, policy);
            if !policy.automatic || c.identity.is_none() || c.start_failed
                || c.idle.found.is_some()
            {
                return;
            }
            if c.active.is_none() {
                if c.retiring.is_some() {
                    c.idle.phase = "Stopping previous search".into();
                    return;
                }
                c.run = c.run.wrapping_add(1).max(1);
                let hash = c.identity.as_ref().and_then(|i| i.hash);
                match Run::start(game, c.world, c.run, hash, policy, c.cache.clone()) {
                    Ok(run) => c.active = Some(run),
                    Err(why) => {
                        c.start_failed = true;
                        c.idle.phase = "Waiting".into();
                        c.idle.detail = Some(why);
                    }
                }
            }
            if let Some(run) = &mut c.active {
                if run.host.cancelled() || run.host.finished.load(Ordering::Acquire)
                    || lock(&run.host.published).found.is_some()
                {
                    return;
                }
                run.scans.refresh(game, &run.latest, run.dimension);
                run.scans.send(&run.input);
            }
        }
        pub(super) fn world_id(game: &Game<'_>) -> u64 {
            if !game.sunset_window() {
                return 0;
            }
            maintain(game);
            lock(&CONTROLLER).world
        }
        pub(super) fn resolved(game: &Game<'_>) -> Option<FoundSeed> {
            if !game.sunset_window() {
                return None;
            }
            maintain(game);
            let c = lock(&CONTROLLER);
            if !c.policy.is_some_and(|p| p.automatic) || c.identity.is_none() {
                return None;
            }
            let snap = c.read();
            if snap.world != c.world || snap.run != c.run {
                return None;
            }
            let found = snap.found?;
            (found.world == c.world && found.run == c.run).then_some(found)
        }
        pub(super) fn snapshot() -> Snapshot {
            let mut c = lock(&CONTROLLER);
            if !RUNTIME.running() {
                c.retire();
                c.policy = None;
            }
            c.read()
        }
        pub(super) fn status_line() -> Option<String> {
            let s = snapshot();
            if s.phase.is_empty() || s.phase == "Off" {
                return None;
            }
            if s.found.is_some() {
                return Some(s.phase);
            }
            if s.total > 0 {
                return Some(
                    format!(
                        "{} {}%", s.phase, (s.checked.saturating_mul(100) / s.total)
                        .min(100)
                    ),
                );
            }
            if s.world_candidates > 0 {
                return Some(format!("{} world candidates", s.world_candidates));
            }
            if s.structure_candidates > 0 {
                return Some(format!("{} structure candidates", s.structure_candidates));
            }
            if s.phase == "Collecting" {
                return Some(format!("Collecting {:.0}/40 bits", s.lifting_bits));
            }
            Some(s.phase)
        }
        pub(super) fn incoming_before(packet: &Clientbound) -> bool {
            if !matches!(
                packet, Clientbound::Login(_) | Clientbound::Respawn(_) |
                Clientbound::Disconnect(_)
            ) {
                return false;
            }
            lock(&CONTROLLER).boundary();
            true
        }
        pub(super) fn restart() {
            stop();
        }
        pub(super) fn stop() {
            let mut c = lock(&CONTROLLER);
            c.retire();
            c.policy = None;
            c.idle.phase = "Off".into();
        }
        #[cfg(test)]
