            fn protection_four_iron_beats_plain_diamond_by_vanilla_reduction() {
                let iron4 = with(item("iron_chestplate"), "protection", 4);
                let diamond = item("diamond_chestplate");
                let iron = item("iron_chestplate");
                assert!(
                    (armor_score(& iron4) - 0.8896).abs() < 0.002, "{}", armor_score(&
                    iron4)
                );
                assert!(
                    (armor_score(& diamond) - 0.80).abs() < 0.002, "{}", armor_score(&
                    diamond)
                );
                assert!(
                    (armor_score(& iron) - 0.6933).abs() < 0.002, "{}", armor_score(&
                    iron)
                );
                assert!(
                    armor_score(& iron4) > armor_score(& diamond) && armor_score(&
                    diamond) > armor_score(& iron)
                );
            }
